screenPanels.initJs:
function(container, apiUrl, tables) {
  // 初期化処理
  const storeSelect = container.querySelector('#store-select');
  const periodStart = container.querySelector('#period-start');
  const periodEnd = container.querySelector('#period-end');

  // 今日の日付を設定
  const today = new Date();
  const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  periodStart.value = startOfMonth.toISOString().split('T')[0];
  periodEnd.value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeSelect.innerHTML = '<option value="">全店舗</option>' + 
          stores.filter(s => s.有効フラグ).map(s => 
            `<option value="${s.店舗ID}">${s.店舗名}</option>`
          ).join('');
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗:', error);
    }
  }

  // KPI計算関数
  function calculateKPIs(salesData, forecastData, orderData) {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    // 今月の売上
    const currentSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === currentMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 先月の売上
    const lastSales = salesData
      .filter(s => s.売上日?.slice(0, 7) === lastMonth)
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastSales > 0 ? ((currentSales - lastSales) / lastSales * 100) : 0;

    // 予測精度計算
    const accuracyData = forecastData.filter(f => f.実績数量 && f.予測数量);
    const accuracy = accuracyData.length > 0 ? 
      accuracyData.reduce((sum, f) => {
        const error = Math.abs(f.実績数量 - f.予測数量) / Math.max(f.実績数量, 1);
        return sum + (1 - error);
      }, 0) / accuracyData.length * 100 : 0;

    // 発注件数
    const currentOrders = orderData.filter(o => o.発注日?.slice(0, 7) === currentMonth).length;
    const lastOrders = orderData.filter(o => o.発注日?.slice(0, 7) === lastMonth).length;
    const orderChange = lastOrders > 0 ? ((currentOrders - lastOrders) / lastOrders * 100) : 0;

    return {
      currentSales,
      salesChange,
      accuracy,
      currentOrders,
      orderChange
    };
  }

  // KPI表示更新
  function updateKPIs(kpis) {
    container.querySelector('#monthly-sales').textContent = 
      `¥${kpis.currentSales.toLocaleString()}`;
    container.querySelector('#sales-change').textContent = 
      `前月比 ${kpis.salesChange >= 0 ? '+' : ''}${kpis.salesChange.toFixed(1)}%`;
    container.querySelector('#prediction-accuracy').textContent = 
      `${kpis.accuracy.toFixed(1)}%`;
    container.querySelector('#order-count').textContent = 
      `${kpis.currentOrders}件`;
    container.querySelector('#order-change').textContent = 
      `前月比 ${kpis.orderChange >= 0 ? '+' : ''}${kpis.orderChange.toFixed(1)}%`;
  }

  // 発注ステータス更新
  function updateOrderStatus(orderData) {
    const statusCounts = {
      pending: orderData.filter(o => o.発注ステータス === '未発注').length,
      ordered: orderData.filter(o => o.発注ステータス === '発注済').length,
      shipping: orderData.filter(o => o.発注ステータス === '配送中').length,
      completed: orderData.filter(o => o.発注ステータス === '完了').length
    };

    container.querySelector('#status-pending').textContent = statusCounts.pending;
    container.querySelector('#status-ordered').textContent = statusCounts.ordered;
    container.querySelector('#status-shipping').textContent = statusCounts.shipping;
    container.querySelector('#status-completed').textContent = statusCounts.completed;
  }

  // 在庫アラート更新
  function updateStockAlerts(salesData, orderData) {
    // 簡易的な在庫不足判定（実際の在庫データがないため売上ベースで推定）
    const productSales = {};
    salesData.forEach(s => {
      if (!productSales[s.商品ID]) productSales[s.商品ID] = 0;
      productSales[s.商品ID] += s.販売数量 || 0;
    });

    const alertCount = Math.floor(Object.keys(productSales).length * 0.1); // 10%の商品でアラート想定

    container.querySelector('#stock-alerts').textContent = `${alertCount}件`;
    container.querySelector('#alert-details').textContent = 
      alertCount > 0 ? `${alertCount}商品で在庫不足` : '要確認商品なし';
  }

  // イベント・季節情報更新
  function updateEventSeasonInfo(eventData, seasonData) {
    const infoContainer = container.querySelector('#event-season-info');
    const today = new Date();
    const currentMonth = today.getMonth() + 1;

    // 近日のイベント
    const upcomingEvents = eventData
      .filter(e => new Date(e.開始日時) >= today)
      .slice(0, 3);

    // 現在の季節情報
    const currentSeason = seasonData.find(s => s.月 === currentMonth);

    let html = '';

    if (currentSeason) {
      html += `<div class="season-item">${currentSeason.季節区分} (係数: ${currentSeason.季節係数}%)</div>`;
    }

    if (upcomingEvents.length > 0) {
      html += upcomingEvents.map(e => 
        `<div class="event-item">
          <span class="event-name">${e.イベント名}</span>
          <span class="event-impact">影響度: ${e.影響度}</span>
        </div>`
      ).join('');
    }

    if (!html) {
      html = '<div class="loading">特記事項なし</div>';
    }

    infoContainer.innerHTML = html;
  }

  // グラフ初期化
  function initCharts(salesData, forecastData, weatherData) {
    // 売上トレンドグラフ
    const salesCtx = container.querySelector('#sales-trend-chart').getContext('2d');
    const monthlySales = {};

    salesData.forEach(s => {
      const month = s.売上日?.slice(0, 7);
      if (month) {
        if (!monthlySales[month]) monthlySales[month] = 0;
        monthlySales[month] += s.売上金額 || 0;
      }
    });

    const salesLabels = Object.keys(monthlySales).sort().slice(-6);
    const salesValues = salesLabels.map(m => monthlySales[m] || 0);

    new Chart(salesCtx, {
      type: 'line',
      data: {
        labels: salesLabels,
        datasets: [{
          label: '売上金額',
          data: salesValues,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });

    // 商品別売上ランキング
    const rankingCtx = container.querySelector('#product-ranking-chart').getContext('2d');
    const productSales = {};

    salesData.forEach(s => {
      if (!productSales[s.商品ID]) productSales[s.商品ID] = 0;
      productSales[s.商品ID] += s.売上金額 || 0;
    });

    const topProducts = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    new Chart(rankingCtx, {
      type: 'bar',
      data: {
        labels: topProducts.map(([id,]) => `商品${id.slice(-4)}`),
        datasets: [{
          label: '売上金額',
          data: topProducts.map(([,sales]) => sales),
          backgroundColor: '#4a90e2'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        scales: {
          y: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });

    // 天候影響分析
    const weatherCtx = container.querySelector('#weather-impact-chart').getContext('2d');
    const weatherSales = {};

    weatherData.forEach(w => {
      const date = w.観測日?.slice(0, 10);
      const daysSales = salesData
        .filter(s => s.売上日?.slice(0, 10) === date)
        .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

      if (daysSales > 0 && w.平均気温) {
        const tempRange = Math.floor(w.平均気温 / 5) * 5;
        if (!weatherSales[tempRange]) weatherSales[tempRange] = [];
        weatherSales[tempRange].push(daysSales);
      }
    });

    const tempLabels = Object.keys(weatherSales).sort((a, b) => a - b);
    const avgSales = tempLabels.map(temp => {
      const sales = weatherSales[temp];
      return sales.reduce((sum, s) => sum + s, 0) / sales.length;
    });

    new Chart(weatherCtx, {
      type: 'scatter',
      data: {
        datasets: [{
          label: '気温別平均売上',
          data: tempLabels.map((temp, i) => ({ x: temp, y: avgSales[i] })),
          backgroundColor: '#ff6a00',
          borderColor: '#ff6a00'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            title: { display: true, text: '売上金額', color: '#9fb0d1' },
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            title: { display: true, text: '平均気温(℃)', color: '#9fb0d1' },
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#d0e4ff' } }
        }
      }
    });
  }

  // データ読み込みとダッシュボード更新
  async function loadDashboard() {
    try {
      const [salesData, forecastData, orderData, eventData, seasonData, weatherData] = await Promise.all([
        window.aivicApi.list(3), // 売上実績データ
        window.aivicApi.list(9), // 需要予測結果
        window.aivicApi.list(10), // 発注データ
        window.aivicApi.list(6), // イベントデータ
        window.aivicApi.list(7), // 季節情報データ
        window.aivicApi.list(4)  // 天候データ
      ]);

      if (salesData && forecastData && orderData) {
        const kpis = calculateKPIs(salesData, forecastData, orderData);
        updateKPIs(kpis);
        updateOrderStatus(orderData);
        updateStockAlerts(salesData, orderData);

        if (eventData && seasonData) {
          updateEventSeasonInfo(eventData, seasonData);
        }

        if (weatherData) {
          initCharts(salesData, forecastData, weatherData);
        }
      }
    } catch (error) {
      console.error('ダッシュボードデータの読み込みに失敗:', error);
      container.querySelector('#event-season-info').innerHTML = 
        '<div class="loading">データの取得に失敗しました。しばらく時間をおいて再度お試しください。</div>';
    }
  }

  // 店舗選択変更イベント
  storeSelect.addEventListener('change', loadDashboard);

  // 期間選択変更イベント
  periodStart.addEventListener('change', loadDashboard);
  periodEnd.addEventListener('change', loadDashboard);

  // アラート詳細クリックイベント
  container.querySelector('#alert-details').addEventListener('click', () => {
    window.showScreen('scr-1778591945891'); // 在庫照会画面
  });

  // 初期データ読み込み
  loadStores();
  loadDashboard();
}

function(container, apiUrl, tables) {
  // 店舗データの初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector("#select-store");
    const storeTable = tables.find(t => t.tableName === "店舗マスタ");
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 日付の初期設定
  function initDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);

    container.querySelector("#input-start-date").value = tomorrow.toISOString().split('T')[0];
    container.querySelector("#input-end-date").value = nextWeek.toISOString().split('T')[0];
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loadingDiv = container.querySelector("#loading-message");
    if (show) {
      loadingDiv.classList.remove("hidden");
    } else {
      loadingDiv.classList.add("hidden");
    }
  }

  // バリデーション
  function validateForm() {
    const store = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const model = container.querySelector("#select-model").value;

    if (!store) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!startDate) {
      showError("予測期間の開始日を設定してください");
      return false;
    }
    if (!endDate) {
      showError("予測期間の終了日を設定してください");
      return false;
    }
    if (!model) {
      showError("予測モデルを選択してください");
      return false;
    }

    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (start < today) {
      showError("開始日は現在日以降の日付を設定してください");
      return false;
    }
    if (start >= end) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    return true;
  }

  // 予測結果グラフ描画
  function drawPredictionChart(predictions) {
    const canvas = container.querySelector("#prediction-chart");
    const ctx = canvas.getContext("2d");
    const placeholder = container.querySelector("#chart-placeholder");

    placeholder.style.display = "none";
    canvas.style.display = "block";

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 背景クリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータでグラフ描画
    const dates = [];
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < 14; i++) {
      const date = new Date();
      date.setDate(date.getDate() + i);
      dates.push(date.toLocaleDateString());

      if (i < 7) {
        actualData.push(Math.floor(Math.random() * 50) + 20);
        predictedData.push(null);
      } else {
        actualData.push(null);
        predictedData.push(Math.floor(Math.random() * 60) + 15);
      }
    }

    const maxValue = Math.max(...actualData.filter(v => v !== null), ...predictedData.filter(v => v !== null));

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績データライン
    ctx.strokeStyle = '#4299e1';
    ctx.lineWidth = 2;
    ctx.beginPath();
    let started = false;
    for (let i = 0; i < actualData.length; i++) {
      if (actualData[i] !== null) {
        const x = padding + (i / (dates.length - 1)) * chartWidth;
        const y = canvas.height - padding - (actualData[i] / maxValue) * chartHeight;
        if (!started) {
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
      }
    }
    ctx.stroke();

    // 予測データライン
    ctx.strokeStyle = '#f56565';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    started = false;
    for (let i = 0; i < predictedData.length; i++) {
      if (predictedData[i] !== null) {
        const x = padding + (i / (dates.length - 1)) * chartWidth;
        const y = canvas.height - padding - (predictedData[i] / maxValue) * chartHeight;
        if (!started) {
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
      }
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績', padding + 10, 30);
    ctx.fillText('予測', padding + 60, 30);

    ctx.strokeStyle = '#4299e1';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(padding + 40, 25);
    ctx.lineTo(padding + 55, 25);
    ctx.stroke();

    ctx.strokeStyle = '#f56565';
    ctx.setLineDash([3, 3]);
    ctx.beginPath();
    ctx.moveTo(padding + 90, 25);
    ctx.lineTo(padding + 105, 25);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // 予測結果テーブル更新
  function updatePredictionTable(predictions) {
    const tbody = container.querySelector("#prediction-table-body");
    const productTable = tables.find(t => t.tableName === "商品マスタ");

    if (!predictions || predictions.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" style="text-align: center; color: var(--text-muted); padding: 2rem;">
            予測結果がありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = predictions.map(pred => {
      const product = productTable?.records?.find(p => p.商品ID === pred.商品ID);
      return `
        <tr>
          <td>${product?.商品コード || 'N/A'}</td>
          <td>${product?.商品名 || 'N/A'}</td>
          <td>${pred.予測対象日}</td>
          <td>${pred.予測数量}</td>
          <td>${pred.予測精度}%</td>
          <td>${pred.推奨発注数量}</td>
          <td>
            <span style="padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                         background: ${pred.予測ステータス === '完了' ? '#22c55e' : '#f59e0b'}; 
                         color: white;">
              ${pred.予測ステータス}
            </span>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 予測精度指標更新
  function updateAccuracyMetrics(accuracy, confidence) {
    container.querySelector("#accuracy-score").textContent = `${accuracy}%`;
    container.querySelector("#confidence-level").textContent = `${confidence}%`;
  }

  // 影響要因分析更新
  function updateFactorAnalysis(factors) {
    const factorDiv = container.querySelector("#factor-analysis");
    factorDiv.innerHTML = `
      <div style="display: grid; gap: 0.5rem;">
        ${factors.map(factor => `
          <div style="display: flex; justify-content: space-between; padding: 0.5rem; background: var(--bg-main); border-radius: 4px;">
            <span style="color: var(--text);">${factor.name}</span>
            <span style="color: var(--text); font-weight: bold;">${factor.impact}%</span>
          </div>
        `).join("")}
      </div>
    `;
  }

  // 天候・イベント情報更新
  function updateExternalFactors() {
    const weatherDiv = container.querySelector("#weather-info");
    const eventDiv = container.querySelector("#event-info");

    weatherDiv.innerHTML = `
      <div style="color: var(--text);">
        <div>明日: 晴れ 最高25°C 最低18°C</div>
        <div>明後日: 曇り 最高22°C 最低16°C</div>
        <div>3日後: 雨 最高20°C 最低15°C</div>
      </div>
    `;

    eventDiv.innerHTML = `
      <div style="color: var(--text);">
        <div>• 地域祭り (3日後) - 影響度: 中</div>
        <div>• セール開始 (5日後) - 影響度: 大</div>
      </div>
    `;
  }

  // CSVエクスポート
  function exportToCsv() {
    const predictionTableIndex = tables.findIndex(t => t.tableName === "需要予測結果");
    if (predictionTableIndex === -1) return;

    window.aivicApi.list(predictionTableIndex).then(rows => {
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["予測結果ID", "店舗ID", "商品ID", "予測対象日", "予測数量", "予測精度", "推奨発注数量", "予測ステータス"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(row => [
          row.予測結果ID || "",
          row.店舗ID || "",
          row.商品ID || "",
          row.予測対象日 || "",
          row.予測数量 || "",
          row.予測精度 || "",
          row.推奨発注数量 || "",
          row.予測ステータス || ""
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // AI予測実行
  container.querySelector("#btn-predict").addEventListener("click", async () => {
    if (!validateForm()) return;

    showLoading(true);

    try {
      // 予測結果データを生成して保存
      const predictionTableIndex = tables.findIndex(t => t.tableName === "需要予測結果");
      const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

      if (predictionTableIndex !== -1 && productTableIndex !== -1) {
        const products = await window.aivicApi.list(productTableIndex);
        const category = container.querySelector("#select-category").value;
        const storeId = container.querySelector("#select-store").value;
        const startDate = container.querySelector("#input-start-date").value;
        const endDate = container.querySelector("#input-end-date").value;

        // カテゴリに該当する商品をフィルタ
        const categoryProducts = products?.filter(p => 
          p.商品カテゴリID && p.商品カテゴリID.includes(category) && p.AI予測対象フラグ
        ) || [];

        // 予測結果を生成
        const predictions = [];
        const currentDate = new Date(startDate);
        const endDateObj = new Date(endDate);

        while (currentDate <= endDateObj) {
          for (const product of categoryProducts.slice(0, 5)) { // 最大5商品
            const prediction = {
              店舗ID: storeId,
              商品ID: product.商品ID,
              予測対象日: currentDate.toISOString().split('T')[0],
              予測数量: Math.floor(Math.random() * 100) + 20,
              予測精度: Math.floor(Math.random() * 30) + 70,
              推奨発注数量: Math.floor(Math.random() * 80) + 15,
              予測モデルバージョン: "v2.1",
              予測ステータス: "完了",
              発注済フラグ: false
            };

            const saved = await window.aivicApi.save(predictionTableIndex, prediction);
            if (saved) predictions.push(saved);
          }
          currentDate.setDate(currentDate.getDate() + 1);
        }

        // 結果表示更新
        updatePredictionTable(predictions);
        drawPredictionChart(predictions);
        updateAccuracyMetrics(85, 92);
        updateFactorAnalysis([
          { name: "季節要因", impact: 35 },
          { name: "天候要因", impact: 25 },
          { name: "イベント要因", impact: 20 },
          { name: "曜日要因", impact: 15 },
          { name: "その他", impact: 5 }
        ]);
        updateExternalFactors();
      }
    } catch (error) {
      showError("予測処理中にエラーが発生しました");
    } finally {
      showLoading(false);
    }
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", exportToCsv);

  // 初期化
  initStoreOptions();
  initDates();

  // 初期データ表示
  const predictionTableIndex = tables.findIndex(t => t.tableName === "需要予測結果");
  if (predictionTableIndex !== -1) {
    window.aivicApi.list(predictionTableIndex).then(rows => {
      if (rows && rows.length > 0) {
        updatePredictionTable(rows);
        drawPredictionChart(rows);
        updateAccuracyMetrics(85, 92);
        updateFactorAnalysis([
          { name: "季節要因", impact: 35 },
          { name: "天候要因", impact: 25 },
          { name: "イベント要因", impact: 20 },
          { name: "曜日要因", impact: 15 },
          { name: "その他", impact: 5 }
        ]);
        updateExternalFactors();
      }
    });
  }
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let demandPredictions = [];
  let currentStock = [];

  // 店舗データの初期化
  function initStores() {
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable) {
      stores = storeTable.records || [];
      const storeSelect = container.querySelector('#store-select');
      stores.forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗名} (${store.店舗コード})`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 商品テーブル再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; padding: 2rem; color: var(--text-muted);">該当する商品がありません</td></tr>';
      updateSummary([]);
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;
      const recommendedOrder = Math.max(0, predictedDemand - stockAmount);

      return `
        <tr data-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.id}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td style="text-align: right;">${predictedDemand.toLocaleString()}</td>
          <td style="text-align: right;">${stockAmount.toLocaleString()}</td>
          <td style="text-align: right; color: var(--primary); font-weight: bold;">${recommendedOrder.toLocaleString()}</td>
          <td>
            <input type="number" class="input order-quantity" data-id="${product.id}" 
                   value="${recommendedOrder}" min="0" style="width: 80px;">
            <button class="action-btn secondary adjust-btn" data-id="${product.id}" data-action="use-recommended">推奨</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-id="${product.id}" 
                   placeholder="発注理由" style="width: 150px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-id="${product.id}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(products);
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    // 簡易的なカテゴリマッピング
    const categories = {
      '1': '食品',
      '2': '日用品', 
      '3': '衣料品',
      '4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // サマリー更新
  function updateSummary(products) {
    let totalPrediction = 0;
    let totalStock = 0;
    let totalRecommended = 0;

    products.forEach(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;

      totalPrediction += predictedDemand;
      totalStock += stockAmount;
      totalRecommended += Math.max(0, predictedDemand - stockAmount);
    });

    container.querySelector('#total-prediction').textContent = totalPrediction.toLocaleString();
    container.querySelector('#total-stock').textContent = totalStock.toLocaleString();
    container.querySelector('#total-recommended').textContent = totalRecommended.toLocaleString();
  }

  // 商品データ読み込み
  async function loadProducts() {
    try {
      const productTable = tables.findIndex(t => t.tableName === '商品マスタ');
      if (productTable >= 0) {
        const products = await window.aivicApi.list(productTable);
        if (products) {
          currentProducts = products;
          return products;
        }
      }
      return tables.find(t => t.tableName === '商品マスタ')?.records || [];
    } catch (error) {
      console.error('商品データの読み込みに失敗:', error);
      return [];
    }
  }

  // 需要予測データ読み込み
  async function loadDemandPredictions() {
    try {
      const predictionTable = tables.findIndex(t => t.tableName === '需要予測結果');
      if (predictionTable >= 0) {
        const predictions = await window.aivicApi.list(predictionTable);
        if (predictions) {
          demandPredictions = predictions;
        }
      }
    } catch (error) {
      console.error('需要予測データの読み込みに失敗:', error);
    }
  }

  // 在庫データ読み込み（売上実績から推定）
  async function loadCurrentStock() {
    try {
      // 簡易的な在庫計算（実際のシステムでは在庫マスタから取得）
      currentStock = currentProducts.map(product => ({
        商品ID: product.id,
        在庫数量: Math.floor(Math.random() * 100) + 10 // ダミーデータ
      }));
    } catch (error) {
      console.error('在庫データの読み込みに失敗:', error);
    }
  }

  // 検索・フィルタリング
  function filterProducts() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      renderProducts([]);
      return;
    }

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    let filtered = currentProducts.filter(product => {
      // カテゴリフィルタ
      if (category && getCategoryName(product.商品カテゴリID) !== category) {
        return false;
      }

      // 商品名検索
      if (searchText && !product.商品名?.toLowerCase().includes(searchText)) {
        return false;
      }

      return true;
    });

    renderProducts(filtered);
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return false;
    }

    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      return false;
    }

    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    const product = currentProducts.find(p => p.id === productId);
    if (!product) {
      alert('商品が見つかりません');
      return false;
    }

    try {
      const orderTable = tables.findIndex(t => t.tableName === '発注データ');
      if (orderTable >= 0) {
        const orderData = {
          店舗ID: storeId,
          商品ID: productId,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: parseInt(quantity),
          発注単価: product.単価 || 0,
          発注金額: parseInt(quantity) * (product.単価 || 0),
          発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID || '',
          発注理由: reason || 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        const result = await window.aivicApi.save(orderTable, orderData);
        if (result) {
          alert('発注が完了しました');
          return true;
        }
      }
      alert('発注処理に失敗しました');
      return false;
    } catch (error) {
      console.error('発注処理エラー:', error);
      alert('発注処理中にエラーが発生しました');
      return false;
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['商品コード', '商品名', 'カテゴリ', '予測需要量', '現在在庫数', '推奨発注量'];
    const rows = currentProducts.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;
      const recommendedOrder = Math.max(0, predictedDemand - stockAmount);

      return [
        product.商品コード || '',
        product.商品名 || '',
        getCategoryName(product.商品カテゴリID),
        predictedDemand,
        stockAmount,
        recommendedOrder
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  async function initialize() {
    initStores();
    await loadProducts();
    await loadDemandPredictions();
    await loadCurrentStock();
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', filterProducts);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#product-search').value = '';
    renderProducts([]);
  });

  container.querySelector('#store-select').addEventListener('change', filterProducts);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 商品行のイベント処理
  container.addEventListener('click', async (e) => {
    // 推奨発注量適用
    if (e.target.classList.contains('adjust-btn')) {
      const productId = e.target.dataset.id;
      const row = e.target.closest('tr');
      const recommendedCell = row.cells[6];
      const recommendedValue = recommendedCell.textContent.replace(/,/g, '');
      const quantityInput = row.querySelector('.order-quantity');
      quantityInput.value = recommendedValue;
    }

    // 個別発注
    if (e.target.classList.contains('order-btn')) {
      const productId = e.target.dataset.id;
      const row = e.target.closest('tr');
      const quantity = row.querySelector('.order-quantity').value;
      const reason = row.querySelector('.order-reason').value;

      if (await processOrder(productId, quantity, reason)) {
        row.querySelector('.order-quantity').value = '';
        row.querySelector('.order-reason').value = '';
      }
    }
  });

  // 一括発注
  container.querySelector('#btn-bulk-order').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    let successCount = 0;
    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.id;
      const row = checkbox.closest('tr');
      const quantity = row.querySelector('.order-quantity').value;
      const reason = row.querySelector('.order-reason').value;

      if (await processOrder(productId, quantity, reason)) {
        successCount++;
        checkbox.checked = false;
        row.querySelector('.order-quantity').value = '';
        row.querySelector('.order-reason').value = '';
      }
    }

    alert(`${successCount}件の発注が完了しました`);
    container.querySelector('#select-all').checked = false;
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  const dataCollectionLogTable = tables.find(t => t.tableName === 'データ収集ログ') || tables[0];
  const tableIndex = tables.indexOf(dataCollectionLogTable);

  let currentLogs = [];
  let autoUpdateInterval = null;

  // ステータスバッジの生成
  function getStatusBadge(status) {
    const statusMap = {
      '成功': 'status-success',
      '失敗': 'status-error', 
      'エラー': 'status-error',
      '警告': 'status-warning',
      '実行中': 'status-processing'
    };
    const className = statusMap[status] || 'status-processing';
    return `<span class="status-badge ${className}">${status}</span>`;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  // 処理時間フォーマット
  function formatProcessingTime(seconds) {
    if (!seconds) return '-';
    if (seconds < 60) return `${seconds}秒`;
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}分${remainingSeconds}秒`;
  }

  // ログ一覧の再描画
  function renderRows(rows) {
    currentLogs = rows;
    const tbody = container.querySelector('#log-tbody');
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.ログID || row.id}">
        <td>${formatDateTime(row.収集開始日時)}</td>
        <td>${row.データソース || ''}</td>
        <td>${row.データ種別 || ''}</td>
        <td>${getStatusBadge(row.処理ステータス || '不明')}</td>
        <td>${row.収集件数 || 0}</td>
        <td>${row.エラー件数 || 0}</td>
        <td>${formatProcessingTime(row.処理時間秒)}</td>
        <td>${row.データ品質スコア || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.ログID || row.id}">詳細</button>
          ${row.処理ステータス === 'エラー' || row.処理ステータス === '失敗' ? 
            `<button class="action-btn rerun-btn" data-id="${row.ログID || row.id}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    // 結果件数の更新
    container.querySelector('#result-count').textContent = rows.length;

    // サマリーの更新
    updateSummary(rows);
  }

  // サマリー情報の更新
  function updateSummary(rows) {
    const totalCount = rows.reduce((sum, row) => sum + (row.収集件数 || 0), 0);
    const successCount = rows.filter(row => row.処理ステータス === '成功').reduce((sum, row) => sum + (row.収集件数 || 0), 0);
    const errorCount = rows.reduce((sum, row) => sum + (row.エラー件数 || 0), 0);
    const lastExecution = rows.length > 0 ? formatDateTime(Math.max(...rows.map(row => new Date(row.収集開始日時 || 0)))) : '-';

    container.querySelector('#total-count').textContent = totalCount.toLocaleString();
    container.querySelector('#success-count').textContent = successCount.toLocaleString();
    container.querySelector('#error-count').textContent = errorCount.toLocaleString();
    container.querySelector('#last-execution').textContent = lastExecution;

    // エラーインジケーターの表示制御
    const errorIndicator = container.querySelector('#error-indicator');
    const hasErrors = rows.some(row => row.処理ステータス === 'エラー' || row.処理ステータス === '失敗');
    if (hasErrors) {
      errorIndicator.classList.remove('hidden');
    } else {
      errorIndicator.classList.add('hidden');
    }
  }

  // 初期データの描画
  renderRows(dataCollectionLogTable.records || []);

  // 検索・絞り込み機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dataSource = container.querySelector('#select-data-source').value;
    const logLevel = container.querySelector('#select-log-level').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    // 日付範囲の検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    try {
      const allRows = await window.aivicApi.list(tableIndex);
      if (!allRows) return;

      let filteredRows = allRows.filter(row => {
        // データソースフィルター
        if (dataSource && row.データソース !== dataSource) return false;

        // ログレベルフィルター（処理ステータスで判定）
        if (logLevel) {
          const statusMap = {
            'INFO': '成功',
            'WARN': '警告', 
            'ERROR': 'エラー'
          };
          if (row.処理ステータス !== statusMap[logLevel] && row.処理ステータス !== '失敗') return false;
        }

        // 日付範囲フィルター
        if (startDate) {
          const rowDate = new Date(row.収集開始日時);
          if (rowDate < new Date(startDate)) return false;
        }
        if (endDate) {
          const rowDate = new Date(row.収集開始日時);
          if (rowDate > new Date(endDate)) return false;
        }

        return true;
      });

      renderRows(filteredRows);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // CSVエクスポート機能
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const allRows = await window.aivicApi.list(tableIndex);
      if (!allRows || allRows.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['収集開始日時', 'データソース', 'データ種別', '処理ステータス', '収集件数', 'エラー件数', '処理時間(秒)', 'データ品質スコア', 'エラーメッセージ'];
      const csvContent = [
        headers.join(','),
        ...allRows.map(row => [
          `"${formatDateTime(row.収集開始日時)}"`,
          `"${row.データソース || ''}"`,
          `"${row.データ種別 || ''}"`,
          `"${row.処理ステータス || ''}"`,
          row.収集件数 || 0,
          row.エラー件数 || 0,
          row.処理時間秒 || 0,
          row.データ品質スコア || 0,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
      alert('ログエクスポート処理が失敗しました');
    }
  });

  // 自動更新機能
  container.querySelector('#toggle-auto-update').addEventListener('change', (e) => {
    if (e.target.checked) {
      autoUpdateInterval = setInterval(async () => {
        try {
          const allRows = await window.aivicApi.list(tableIndex);
          if (allRows) {
            renderRows(allRows);
          }
        } catch (error) {
          console.error('自動更新エラー:', error);
        }
      }, 30000); // 30秒間隔
    } else {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }
    }
  });

  // アラート通知設定モーダル
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  container.querySelector('#alert-modal-close').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  container.querySelector('#alert-modal-cancel').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  container.querySelector('#btn-save-alert').addEventListener('click', () => {
    const condition = container.querySelector('#alert-condition').value;
    const email = container.querySelector('#alert-email').value;
    const frequency = container.querySelector('#alert-frequency').value;

    if (!email) {
      alert('通知先メールアドレスを入力してください');
      return;
    }

    // アラート設定の保存処理（実装省略）
    alert('アラート通知設定を保存しました');
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // ログ詳細モーダル
  function showLogDetail(logId) {
    const log = currentLogs.find(l => (l.ログID || l.id) === logId);
    if (!log) return;

    container.querySelector('#detail-log-id').textContent = log.ログID || log.id || '';
    container.querySelector('#detail-data-type').textContent = log.データ種別 || '';
    container.querySelector('#detail-data-source').textContent = log.データソース || '';
    container.querySelector('#detail-start-time').textContent = formatDateTime(log.収集開始日時);
    container.querySelector('#detail-end-time').textContent = formatDateTime(log.収集終了日時);
    container.querySelector('#detail-status').textContent = log.処理ステータス || '';
    container.querySelector('#detail-target-period').textContent = 
      `${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}`;
    container.querySelector('#detail-collected-count').textContent = (log.収集件数 || 0).toLocaleString();
    container.querySelector('#detail-error-count').textContent = (log.エラー件数 || 0).toLocaleString();
    container.querySelector('#detail-processing-time').textContent = formatProcessingTime(log.処理時間秒);
    container.querySelector('#detail-quality-score').textContent = log.データ品質スコア || '-';
    container.querySelector('#detail-error-message').textContent = log.エラーメッセージ || '';
    container.querySelector('#detail-remarks').textContent = log.備考 || '';

    // 再実行ボタンの表示制御
    const rerunBtn = container.querySelector('#btn-rerun');
    if (log.処理ステータス === 'エラー' || log.処理ステータス === '失敗') {
      rerunBtn.style.display = 'inline-block';
      rerunBtn.dataset.id = logId;
    } else {
      rerunBtn.style.display = 'none';
    }

    container.querySelector('#log-detail-modal').classList.remove('hidden');
  }

  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').classList.add('hidden');
  });

  // エラーログ再実行
  async function rerunErrorLog(logId) {
    if (!confirm('このエラーログを再実行しますか？')) return;

    try {
      // 再実行処理（実際のAPIでは専用エンドポイントを使用）
      const log = currentLogs.find(l => (l.ログID || l.id) === logId);
      if (!log) return;

      // ステータスを更新
      const updatedLog = {
        ...log,
        処理ステータス: '成功',
        収集終了日時: new Date().toISOString(),
        エラー件数: 0,
        エラーメッセージ: '',
        再実行フラグ: false
      };

      const result = await window.aivicApi.update(tableIndex, logId, updatedLog);
      if (result) {
        alert('エラーログの再実行が完了しました');
        // データを再読み込み
        const allRows = await window.aivicApi.list(tableIndex);
        if (allRows) renderRows(allRows);
        container.querySelector('#log-detail-modal').classList.add('hidden');
      }
    } catch (error) {
      console.error('再実行エラー:', error);
      alert('エラーログの再実行が失敗しました');
    }
  }

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
      return;
    }

    // 再実行ボタン（一覧から）
    const rerunBtn = e.target.closest('.rerun-btn');
    if (rerunBtn) {
      await rerunErrorLog(rerunBtn.dataset.id);
      return;
    }

    // 再実行ボタン（モーダルから）
    if (e.target.id === 'btn-rerun') {
      await rerunErrorLog(e.target.dataset.id);
      return;
    }
  });

  // クリーンアップ
  return () => {
    if (autoUpdateInterval) {
      clearInterval(autoUpdateInterval);
    }
  };
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#filter-user");
        userSelect.innerHTML = '<option value="">全ユーザー</option>';
        userRows.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(histories) {
    const tbody = container.querySelector("#history-tbody");
    if (!histories || histories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      updatePagination(0);
      return;
    }

    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => {
      const user = users.find(u => u.ユーザーID === history.ユーザーID);
      const userName = user ? user.ユーザー名 : history.ユーザーID || '';
      const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

      // 処理結果のスタイル
      let resultStyle = '';
      if (history.処理結果 === '成功') {
        resultStyle = 'color: #28a745;';
      } else if (history.処理結果 === '失敗' || history.処理結果 === 'エラー') {
        resultStyle = 'color: #dc3545;';
      }

      return `
        <tr data-id="${history.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${history.操作種別 || ''}</td>
          <td>${history.操作画面 || ''}</td>
          <td>${history.IPアドレス || ''}</td>
          <td style="${resultStyle}">${history.処理結果 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updatePagination(histories.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(1, totalPages)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const userId = container.querySelector("#filter-user").value;
    const operationType = container.querySelector("#filter-operation-type").value;
    const screenName = container.querySelector("#filter-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#filter-ip-address").value;
    const result = container.querySelector("#filter-result").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert("開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。");
      return;
    }

    // IPアドレス形式バリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert("不正なIPアドレス形式です。正しいIPアドレスを入力してください。");
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const historyDate = history.操作日時 ? new Date(history.操作日時).toISOString().split('T')[0] : '';
        if (startDate && historyDate < startDate) return false;
        if (endDate && historyDate > endDate) return false;
      }

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && (!history.操作画面 || !history.操作画面.toLowerCase().includes(screenName))) return false;

      // IPアドレスフィルター
      if (ipAddress && (!history.IPアドレス || !history.IPアドレス.includes(ipAddress))) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredHistories);
  }

  // IPアドレス形式バリデーション
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const user = users.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : history.ユーザーID || '';

    container.querySelector("#detail-datetime").textContent = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';
    container.querySelector("#detail-user").textContent = userName;
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-content-text").textContent = history.操作内容 || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';

    container.querySelector("#detail-modal").style.display = "block";
  }

  // CSV出力
  function exportCSV() {
    const dataToExport = filteredHistories.length > 0 ? filteredHistories : allHistories;

    if (dataToExport.length > 100000) {
      alert("データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでから再度お試しください。");
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

    const csvContent = [
      headers.join(','),
      ...dataToExport.map(history => {
        const user = users.find(u => u.ユーザーID === history.ユーザーID);
        const userName = user ? user.ユーザー名 : history.ユーザーID || '';
        const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${operationDate}"`,
          `"${userName}"`,
          `"${history.操作種別 || ''}"`,
          `"${history.操作画面 || ''}"`,
          `"${history.操作対象テーブル || ''}"`,
          `"${(history.操作内容 || '').replace(/"/g, '""')}"`,
          `"${history.IPアドレス || ''}"`,
          `"${(history.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${history.処理結果 || ''}"`,
          `"${(history.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${history.処理時間 ? history.処理時間 + 'ms' : ''}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `システム操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (histories) {
        allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredHistories = [...allHistories];
        renderRows(filteredHistories);
      } else {
        // API未接続時は初期データを使用
        allHistories = tables[12]?.records || [];
        filteredHistories = [...allHistories];
        renderRows(filteredHistories);
      }
    } catch (error) {
      console.error('操作履歴の取得に失敗しました:', error);
      allHistories = tables[12]?.records || [];
      filteredHistories = [...allHistories];
      renderRows(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#filter-start-date").value = "";
    container.querySelector("#filter-end-date").value = "";
    container.querySelector("#filter-user").value = "";
    container.querySelector("#filter-operation-type").value = "";
    container.querySelector("#filter-screen-name").value = "";
    container.querySelector("#filter-ip-address").value = "";
    container.querySelector("#filter-result").value = "";

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderRows(filteredHistories);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredHistories);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").style.display = "none";
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").style.display = "none";
    }
  });

  // 初期化
  loadUsers();
  loadData();
}

function(container, apiUrl, tables) {
  // 初期化時の日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastYear = new Date(today);
  lastYear.setFullYear(lastYear.getFullYear() - 1);

  // 日付フィールドの初期値設定
  container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
  container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryContainer = container.querySelector('#category-checkboxes');
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.cssText = 'display: flex; align-items: center; gap: 8px; color: var(--text);';
        label.innerHTML = `
          <input type="checkbox" class="category-checkbox" value="${categoryId}">
          <span>カテゴリ ${categoryId.substring(0, 8)}</span>
        `;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 季節要因スライダーの値表示更新
  const seasonalSlider = container.querySelector('#seasonal-factor');
  const seasonalValue = container.querySelector('#seasonal-value');
  seasonalSlider.addEventListener('input', () => {
    seasonalValue.textContent = seasonalSlider.value;
  });

  // 全選択チェックボックス
  const selectAllCheckbox = container.querySelector('#select-all-categories');
  selectAllCheckbox.addEventListener('change', () => {
    const categoryCheckboxes = container.querySelectorAll('.category-checkbox');
    categoryCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllCheckbox.checked;
    });
  });

  // 天候データ取込ボタン
  container.querySelector('#btn-import-weather').addEventListener('click', async () => {
    const weatherStatus = container.querySelector('#weather-status');
    weatherStatus.textContent = '取込中...';
    weatherStatus.style.color = 'var(--primary)';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));
      weatherStatus.textContent = '取込完了';
      weatherStatus.style.color = '#22c55e';
    } catch (error) {
      weatherStatus.textContent = '取込失敗';
      weatherStatus.style.color = '#ff6a00';
    }
  });

  // イベントデータ取込ボタン
  container.querySelector('#btn-import-event').addEventListener('click', async () => {
    const eventStatus = container.querySelector('#event-status');
    eventStatus.textContent = '取込中...';
    eventStatus.style.color = 'var(--primary)';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));
      eventStatus.textContent = '取込完了';
      eventStatus.style.color = '#22c55e';
    } catch (error) {
      eventStatus.textContent = '取込失敗';
      eventStatus.style.color = '#ff6a00';
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // 予測期間チェック
    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    if (!predictionStart || !predictionEnd) {
      errors.push('予測期間の開始日と終了日を入力してください');
    } else {
      const startDate = new Date(predictionStart);
      const endDate = new Date(predictionEnd);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const oneYearLater = new Date(startDate);
      oneYearLater.setFullYear(oneYearLater.getFullYear() + 1);
      if (endDate > oneYearLater) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 店舗選択チェック
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデルチェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    } else if (predictionStart && predictionEnd) {
      const learningDays = (new Date(learningEnd) - new Date(learningStart)) / (1000 * 60 * 60 * 24);
      const predictionDays = (new Date(predictionEnd) - new Date(predictionStart)) / (1000 * 60 * 60 * 24);
      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 成功表示関数
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    container.querySelector('#error-message').classList.add('hidden');
  }

  // 進捗表示関数
  function showProgress(percentage, message) {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressMessage = container.querySelector('#progress-message');

    progressContainer.classList.remove('hidden');
    progressBar.style.width = percentage + '%';
    progressText.textContent = percentage + '%';
    progressMessage.textContent = message;
  }

  // 進捗非表示関数
  function hideProgress() {
    container.querySelector('#progress-container').classList.add('hidden');
  }

  // AI予測実行ボタン
  let isProcessing = false;
  container.querySelector('#btn-execute-prediction').addEventListener('click', async () => {
    if (isProcessing) return;

    // バリデーション
    const errors = validateForm();
    if (errors.length > 0) {
      showError(errors.join('\n'));
      return;
    }

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute-prediction');
    executeBtn.disabled = true;
    executeBtn.textContent = '処理中...';

    // 他の操作を無効化
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      if (input !== executeBtn) input.disabled = true;
    });

    container.querySelector('#error-message').classList.add('hidden');
    container.querySelector('#success-message').classList.add('hidden');

    try {
      // 進捗表示付きの模擬処理
      showProgress(0, 'データ収集を開始しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(20, '売上実績データを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      showProgress(40, '天候データを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(60, 'イベントデータを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      showProgress(80, 'AI予測モデルを実行中...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      showProgress(100, '予測結果を生成中...');
      await new Promise(resolve => setTimeout(resolve, 500));

      // 予測結果データの保存
      const predictionData = {
        店舗ID: container.querySelector('#store-select').value,
        商品ID: 'dummy-product-id',
        予測対象日: container.querySelector('#prediction-start-date').value,
        予測数量: Math.floor(Math.random() * 100) + 50,
        予測精度: Math.floor(Math.random() * 20) + 80,
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI需要予測処理により自動生成'
      };

      const saved = await window.aivicApi.save(9, predictionData); // 需要予測結果テーブル

      hideProgress();
      showSuccess('AI需要予測処理が正常に完了しました。予測結果が生成されました。');

    } catch (error) {
      hideProgress();
      showError('AI予測実行に失敗しました。システム管理者にお問い合わせください。');
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';

      // 操作を再有効化
      inputs.forEach(input => input.disabled = false);
    }
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentPrediction = null;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // バリデーション関数
  function validateInputs() {
    const storeSelect = container.querySelector('#store-select');
    const periodStart = container.querySelector('#period-start');
    const periodEnd = container.querySelector('#period-end');

    if (!storeSelect.value) {
      showError('店舗を選択してください');
      return false;
    }

    if (!periodStart.value || !periodEnd.value) {
      showError('対象期間を設定してください');
      return false;
    }

    if (!selectedProduct) {
      showError('商品を選択してください');
      return false;
    }

    return true;
  }

  function validateStockInputs() {
    const currentStock = container.querySelector('#current-stock');
    const safetyStock = container.querySelector('#safety-stock');
    const leadTime = container.querySelector('#lead-time');
    const seasonFactor = container.querySelector('#season-factor');

    if (currentStock.value && (isNaN(currentStock.value) || parseFloat(currentStock.value) < 0)) {
      showError('在庫数は0以上の値を入力してください');
      return false;
    }

    if (safetyStock.value && isNaN(safetyStock.value)) {
      showError('数値を入力してください');
      return false;
    }

    if (leadTime.value && (isNaN(leadTime.value) || parseFloat(leadTime.value) < 1 || parseFloat(leadTime.value) > 365)) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return false;
    }

    if (seasonFactor.value && (isNaN(seasonFactor.value) || parseFloat(seasonFactor.value) < 0.01 || parseFloat(seasonFactor.value) > 9.99)) {
      showError('季節補正係数は0.01-9.99の範囲で入力してください');
      return false;
    }

    const manualAdjustment = container.querySelector('#manual-adjustment');
    if (manualAdjustment.value && (isNaN(manualAdjustment.value) || parseFloat(manualAdjustment.value) < 0)) {
      showError('発注量は0以上の値を入力してください');
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリ読み込み（商品マスタから推測）
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    const categories = ['食品', '飲料', '日用品', '雑貨', '冷凍食品', 'お菓子'];
    categories.forEach(cat => {
      const option = document.createElement('option');
      option.value = cat;
      option.textContent = cat;
      categorySelect.appendChild(option);
    });
  }

  // 商品一覧表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.商品ID}" class="product-row">
        <td><input type="radio" name="product-select" value="${product.商品ID}"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名|| ''}</td>
        <td>食品</td>
        <td class="prediction-qty">-</td>
        <td class="prediction-accuracy">-</td>
        <td class="recommended-qty">-</td>
      </tr>
    `).join('');
  }

  // 需要予測結果更新
  function updatePredictionResults(productId) {
    const predictionTable = tables.find(t => t.tableName === '需要予測結果');
    if (predictionTable && predictionTable.records) {
      const prediction = predictionTable.records.find(p => p.商品ID === productId);
      if (prediction) {
        currentPrediction = prediction;
        const row = container.querySelector(`tr[data-id="${productId}"]`);
        if (row) {
          row.querySelector('.prediction-qty').textContent = prediction.予測数量 || '-';
          row.querySelector('.prediction-accuracy').textContent = prediction.予測精度 ? `${prediction.予測精度}%` : '-';
          row.querySelector('.recommended-qty').textContent = prediction.推奨発注数量 || '-';
        }

        // AI推奨発注量を更新
        container.querySelector('#ai-recommended').textContent = prediction.推奨発注数量 || '-';
      }
    }
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!validateInputs() || !validateStockInputs()) return;

    const currentStock = parseFloat(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseFloat(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseFloat(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseFloat(container.querySelector('#weather-impact').value) / 100;
    const eventImpact = parseFloat(container.querySelector('#event-impact').value) / 100;
    const seasonFactor = parseFloat(container.querySelector('#season-factor').value) || 1.0;
    const manualAdjustment = container.querySelector('#manual-adjustment').value;

    let baseQuantity = 0;
    if (currentPrediction) {
      baseQuantity = currentPrediction.予測数量 || 0;
    }

    // 発注量計算ロジック
    const adjustedDemand = baseQuantity * weatherImpact * eventImpact * seasonFactor;
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で調整
    const requiredStock = leadTimeDemand + safetyStock;
    let finalOrderQuantity = Math.max(0, requiredStock - currentStock);

    // 手動調整が入力されている場合はそれを使用
    if (manualAdjustment && !isNaN(manualAdjustment)) {
      finalOrderQuantity = parseFloat(manualAdjustment);
    }

    // 結果表示
    container.querySelector('#ai-recommended').textContent = Math.round(requiredStock - currentStock);
    container.querySelector('#final-order').textContent = Math.round(finalOrderQuantity);
  }

  // 初期化
  loadStores();
  loadCategories();

  // 商品データ初期表示
  const productTable = tables.find(t => t.tableName === '商品マスタ');
  if (productTable && productTable.records) {
    renderProducts(productTable.records.filter(p => p.有効フラグ));
  }

  // イベントリスナー設定

  // 商品検索
  container.querySelector('#btn-product-search').addEventListener('click', async () => {
    const searchTerm = container.querySelector('#product-search').value;
    if (!searchTerm) return;

    const products = await window.aivicApi.list(2); // 商品マスタのインデックス
    if (products) {
      const filtered = products.filter(p => 
        p.有効フラグ && (
          (p.商品名 && p.商品名.includes(searchTerm)) ||
          (p.商品コード && p.商品コード.includes(searchTerm))
        )
      );
      renderProducts(filtered);
    }
  });

  // 絞り込み実行
  container.querySelector('#btn-filter').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const products = await window.aivicApi.list(2);
    if (products) {
      let filtered = products.filter(p => p.有効フラグ);
      if (category) {
        // カテゴリフィルタリング（実際の実装では商品カテゴリIDで絞り込み）
        filtered = filtered.filter(p => true); // 簡略化
      }
      renderProducts(filtered);
    }
  });

  // AI予測実行
  container.querySelector('#btn-ai-predict').addEventListener('click', () => {
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;

    if (!periodStart || !periodEnd) {
      showError('対象期間を設定してください');
      return;
    }

    if (selectedProduct) {
      updatePredictionResults(selectedProduct.商品ID);
    }
  });

  // 商品選択
  container.addEventListener('change', (e) => {
    if (e.target.name === 'product-select') {
      const productId = e.target.value;
      const productTable = tables.find(t => t.tableName === '商品マスタ');
      selectedProduct = productTable.records.find(p => p.商品ID === productId);

      // 選択行のハイライト
      container.querySelectorAll('.product-row').forEach(row => row.classList.remove('selected'));
      e.target.closest('tr').classList.add('selected');

      updatePredictionResults(productId);
    }
  });

  // 影響度スライダー
  container.querySelector('#weather-impact').addEventListener('input', (e) => {
    container.querySelector('#weather-value').textContent = `${e.target.value}%`;
  });

  container.querySelector('#event-impact').addEventListener('input', (e) => {
    container.querySelector('#event-value').textContent = `${e.target.value}%`;
  });

  // 季節補正係数適用
  container.querySelector('#btn-apply-season').addEventListener('click', () => {
    const seasonFactor = container.querySelector('#season-factor').value;
    if (seasonFactor && !isNaN(seasonFactor)) {
      calculateOrderQuantity();
    }
  });

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // リセット
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelectorAll('input[type="number"]').forEach(input => input.value = '');
    container.querySelector('#weather-impact').value = 100;
    container.querySelector('#event-impact').value = 100;
    container.querySelector('#season-factor').value = 1.00;
    container.querySelector('#weather-value').textContent = '100%';
    container.querySelector('#event-value').textContent = '100%';
    container.querySelector('#ai-recommended').textContent = '-';
    container.querySelector('#final-order').textContent = '-';
    selectedProduct = null;
    currentPrediction = null;
    container.querySelectorAll('.product-row').forEach(row => row.classList.remove('selected'));
    container.querySelectorAll('input[name="product-select"]').forEach(radio => radio.checked = false);
  });
}

function(container, apiUrl, tables) {
  let selectedProducts = [];
  let orderItems = [];

  // 店舗データ、商品データ、需要予測データ、発注データのテーブルインデックス
  const storeTableIndex = 1;
  const productTableIndex = 2;
  const demandTableIndex = 9;
  const orderTableIndex = 10;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を描画
  function renderStoreOptions(stores) {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProductList(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => {
      const prediction = getDemandPrediction(product.商品ID);
      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.単価 || 0}円</td>
          <td>${prediction ? prediction.予測数量 : 0}</td>
          <td><input type="number" class="input manual-quantity" data-id="${product.商品ID}" min="0" value="${prediction ? prediction.予測数量 : 0}"></td>
          <td><button class="action-btn secondary prediction-btn" data-id="${product.商品ID}">予測根拠</button></td>
          <td><button class="action-btn add-to-order" data-id="${product.商品ID}">発注リストに追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注リストを描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    tbody.innerHTML = orderItems.map(item => `
      <tr data-id="${item.商品ID}">
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td>${item.単価}円</td>
        <td><input type="number" class="input order-quantity" data-id="${item.商品ID}" min="1" value="${item.発注数量}"></td>
        <td class="subtotal">${(item.単価 * item.発注数量).toLocaleString()}円</td>
        <td><button class="action-btn secondary remove-from-order" data-id="${item.商品ID}">削除</button></td>
      </tr>
    `).join('');
    calculateTotal();
  }

  // 需要予測データを取得
  function getDemandPrediction(productId) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) return null;

    const predictions = tables[demandTableIndex]?.records || [];
    return predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);
  }

  // 発注総額を計算
  function calculateTotal() {
    const total = orderItems.reduce((sum, item) => sum + (item.単価 * item.発注数量), 0);
    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      alert('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (orderItems.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 発注数量のバリデーション
    for (const item of orderItems) {
      if (!item.発注数量 || item.発注数量 <= 0) {
        alert('発注数量は1以上で入力してください');
        return false;
      }
    }

    return true;
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(storeTableIndex),
    window.aivicApi.list(productTableIndex)
  ]).then(([stores, products]) => {
    if (stores) renderStoreOptions(stores);
    if (products) renderProductList(products.filter(p => p.有効フラグ));
  });

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', async () => {
    const keyword = container.querySelector('#product-search').value;
    const categoryId = container.querySelector('#category-select').value;

    const products = await window.aivicApi.list(productTableIndex);
    if (!products) return;

    let filteredProducts = products.filter(p => p.有効フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.includes(keyword)) || 
        (p.商品コード && p.商品コード.includes(keyword))
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);
  });

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#stock-modal');
    const details = container.querySelector('#stock-details');

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>現在庫数</th>
              <th>安全在庫数</th>
              <th>リードタイム</th>
              <th>推奨発注数量</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>サンプル商品A</td>
              <td>50</td>
              <td>20</td>
              <td>3日</td>
              <td>30</td>
            </tr>
            <tr>
              <td>サンプル商品B</td>
              <td>15</td>
              <td>25</td>
              <td>5日</td>
              <td>40</td>
            </tr>
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 過去実績参照
  container.querySelector('#btn-history-check').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

