        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>先月発注量</th>
              <th>先月売上量</th>
              <th>2ヶ月前発注量</th>
              <th>2ヶ月前売上量</th>
              <th>3ヶ月前発注量</th>
              <th>3ヶ月前売上量</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>サンプル商品A</td>
              <td>100</td>
              <td>95</td>
              <td>120</td>
              <td>118</td>
              <td>90</td>
              <td>88</td>
            </tr>
            <tr>
              <td>サンプル商品B</td>
              <td>80</td>
              <td>75</td>
              <td>85</td>
              <td>82</td>
              <td>70</td>
              <td>68</td>
            </tr>
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 発注総額表示
  container.querySelector('#btn-calculate-total').addEventListener('click', () => {
    calculateTotal();
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.単価 * item.発注数量,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(orderTableIndex, orderData);
      }

      alert('発注書が正常に作成されました');

      // フォームをリセット
      orderItems = [];
      renderOrderList();
      container.querySelector('#store-select').value = '';
