      if (!product) return;

      const manualQuantity = container.querySelector(`.manual-quantity[data-id="${productId}"]`).value;
      const quantity = parseInt(manualQuantity) || 1;

      if (quantity <= 0) {
        alert('発注数量は1以上で入力してください');
        return;
