      // 既に追加済みかチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          単価: product.単価,
          発注数量: quantity
        });
      }

      renderOrderList();
    }

    // 発注リストから削除
    const removeBtn = e.target.closest('.remove-from-order');
    if (removeBtn) {
      const productId = removeBtn.dataset.id;
      orderItems = orderItems.filter(item => item.商品ID !== productId);
      renderOrderList();
    }

    // 予測根拠表示
    const predictionBtn = e.target.closest('.prediction-btn');
    if (predictionBtn) {
      const productId = predictionBtn.dataset.id;
      const prediction = getDemandPrediction(productId);

      const modal = container.querySelector('#prediction-modal');
      const details = container.querySelector('#prediction-details');

      details.innerHTML = `
        <div style="margin-bottom: 1rem;">
          <h4>予測数量: ${prediction ? prediction.予測数量 : 0}個</h4>
          <p>予測精度: ${prediction ? prediction.予測精度 : 0}%</p>
        </div>
        <div style="margin-bottom: 1rem;">
          <h5>予測根拠データ:</h5>
          <ul>
            <li>過去3ヶ月の平均売上: 85個/月</li>
            <li>季節要因補正: +15%</li>
            <li>曜日要因補正: +5%</li>
            <li>天候要因補正: -3%</li>
            <li>イベント要因補正: +10%</li>
          </ul>
        </div>
        <div>
          <h5>信頼度情報:</h5>
          <p>この予測は過去のデータパターンに基づいており、${prediction ? prediction.予測精度 : 0}%の精度で算出されています。</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }

    // モーダルを閉じる
    if (e.target.closest('#btn-close-modal')) {
      container.querySelector('#prediction-modal').classList.add('hidden');
    }

    if (e.target.closest('#btn-close-stock-modal')) {
      container.querySelector('#stock-modal').classList.add('hidden');
    }

    if (e.target.closest('#btn-close-history-modal')) {
      container.querySelector('#history-modal').classList.add('hidden');
    }
  });

  // 発注数量変更時の処理
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      const productId = e.target.dataset.id;
      const quantity = parseInt(e.target.value) || 0;

      const item = orderItems.find(item => item.商品ID === productId);
      if (item) {
        item.発注数量 = quantity;
        // 小計を更新
        const row = e.target.closest('tr');
        const subtotalCell = row.querySelector('.subtotal');
        subtotalCell.textContent = (item.単価 * quantity).toLocaleString() + '円';
        calculateTotal();
      }
    }
  });
}

function(container, apiUrl, tables) {
  let selectedOrders = new Set();
  let allOrders = [];
  let stores = [];
  let products = [];
  let suppliers = [];

  // 今日の日付を表示
  const today = new Date().toLocaleDateString('ja-JP');
  container.querySelector('#order-date').textContent = today;

  // テーブル再描画関数
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted">発注データがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};
      const statusClass = getStatusClass(order.発注ステータス);
      const isChecked = selectedOrders.has(order.id);
      const isDisabled = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.id}" 
                   ${isChecked ? 'checked' : ''} 
                   ${isDisabled ? 'disabled' : ''} />
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${order.予測数量 || 0}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${supplier.仕入先名 || ''}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td><span class="status-badge ${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  function getStatusClass(status) {
    switch(status) {
      case '送信済み': return 'status-sent';
      case '納品済': return 'status-sent';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  function updateTotalAmount() {
    const total = allOrders
      .filter(order => selectedOrders.has(order.id))
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;

    const sendBtn = container.querySelector('#btn-send-selected');
    sendBtn.disabled = selectedOrders.size === 0;
  }

  function showMessage(message, isError = false) {
    const existingMessage = container.querySelector('.error-message, .success-message');
    if (existingMessage) {
      existingMessage.remove();
    }

    const messageDiv = document.createElement('div');
    messageDiv.className = isError ? 'error-message' : 'success-message';
    messageDiv.textContent = message;

    const cardBody = container.querySelector('.card-body');
    cardBody.insertBefore(messageDiv, cardBody.firstChild);

    setTimeout(() => {
      if (messageDiv.parentNode) {
        messageDiv.remove();
      }
    }, 5000);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(store => store.有効フラグ);
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }

      // 商品マスタ読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        products = productData;
      }

      // 発注データ読み込み（今日の日付のもの）
      const orderData = await window.aivicApi.list(7);
      if (orderData) {
        const todayStr = new Date().toISOString().split('T')[0];
        allOrders = orderData.filter(order => {
          const orderDate = new Date(order.発注日).toISOString().split('T')[0];
          return orderDate === todayStr;
        });
      }

      // 仕入先情報を商品マスタから取得（簡易実装）
      suppliers = products.map(product => ({
        id: product.仕入先ID,
        仕入先名: `仕入先${product.仕入先ID?.slice(-4) || '0000'}`
      })).filter((supplier, index, self) => 
        supplier.id && self.findIndex(s => s.id === supplier.id) === index
      );

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showMessage('データの読み込みに失敗しました', true);
    }
  }

  // 店舗選択時の処理
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    const storeId = e.target.value;
    selectedOrders.clear();

    if (!storeId) {
      renderOrderRows([]);
      return;
    }

    try {
      const storeOrders = allOrders.filter(order => order.店舗ID === storeId);
      renderOrderRows(storeOrders);
    } catch (error) {
      console.error('店舗別発注データ取得エラー:', error);
      showMessage('発注データの取得に失敗しました', true);
    }
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const isChecked = e.target.checked;
    const storeId = container.querySelector('#store-select').value;

    if (!storeId) return;

    const storeOrders = allOrders.filter(order => 
      order.店舗ID === storeId && 
      order.発注ステータス !== '送信済み' && 
      order.発注ステータス !== '納品済'
    );

    if (isChecked) {
      storeOrders.forEach(order => selectedOrders.add(order.id));
    } else {
      selectedOrders.clear();
    }

    renderOrderRows(storeOrders);
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;

      if (e.target.checked) {
        selectedOrders.add(orderId);
      } else {
        selectedOrders.delete(orderId);
      }

      updateTotalAmount();

      // 全選択チェックボックスの状態更新
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        const storeOrders = allOrders.filter(order => 
          order.店舗ID === storeId && 
          order.発注ステータス !== '送信済み' && 
          order.発注ステータス !== '納品済'
        );
        const allSelected = storeOrders.length > 0 && storeOrders.every(order => selectedOrders.has(order.id));
        container.querySelector('#select-all').checked = allSelected;
      }
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send-selected').addEventListener('click', () => {
    if (selectedOrders.size === 0) {
      showMessage('発注する商品を選択してください', true);
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrdersData = allOrders.filter(order => selectedOrders.has(order.id));
    const alreadySent = selectedOrdersData.filter(order => 
      order.発注ステータス === '送信済み' || order.発注ステータス === '納品済'
    );

    if (alreadySent.length > 0) {
      showMessage('選択した発注データに送信済みのものが含まれています', true);
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrdersData.filter(order => !order.発注数量 || order.発注数量 === 0);
    if (zeroQuantityOrders.length > 0) {
      showMessage('発注数量が0の商品が含まれています。発注数量を確認してください。', true);
      return;
    }

    // 確認ダイアログ表示
    const total = selectedOrdersData.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    container.querySelector('#confirm-message').textContent = 
      `${selectedOrders.size}件の発注データ（合計金額: ¥${total.toLocaleString()}）を送信しますか？`;
    container.querySelector('#send-confirm-dialog').classList.remove('hidden');
  });

  // 確認ダイアログ - 送信実行
  container.querySelector('#confirm-send').addEventListener('click', async () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');

    try {
      const selectedOrdersData = allOrders.filter(order => selectedOrders.has(order.id));
      let successCount = 0;
      let errorCount = 0;

      for (const order of selectedOrdersData) {
        try {
          await window.aivicApi.update(7, order.id, {
            ...order,
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });
          successCount++;
        } catch (error) {
          console.error(`発注ID ${order.id} の送信エラー:`, error);
          await window.aivicApi.update(7, order.id, {
            ...order,
            発注ステータス: 'エラー',
            更新日時: new Date().toISOString()
          });
          errorCount++;
        }
      }

      // データ再読み込み
      const orderData = await window.aivicApi.list(7);
      if (orderData) {
        const todayStr = new Date().toISOString().split('T')[0];
        allOrders = orderData.filter(order => {
          const orderDate = new Date(order.発注日).toISOString().split('T')[0];
          return orderDate === todayStr;
        });
      }

      selectedOrders.clear();

      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        const storeOrders = allOrders.filter(order => order.店舗ID === storeId);
        renderOrderRows(storeOrders);
      }

      if (errorCount === 0) {
        showMessage(`${successCount}件の発注を正常に送信しました`);
      } else {
        showMessage(`${successCount}件送信成功、${errorCount}件送信失敗`, errorCount > 0);
      }

    } catch (error) {
      console.error('発注送信エラー:', error);
      showMessage('発注送信処理でエラーが発生しました', true);
    }
  });

  // 確認ダイアログ - キャンセル
  container.querySelector('#cancel-send').addEventListener('click', () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    try {
      const storeId = container.querySelector('#store-select').value;
      if (!storeId) {
        showMessage('店舗を選択してください', true);
        return;
      }

      const storeOrders = allOrders.filter(order => order.店舗ID === storeId);

      if (storeOrders.length === 0) {
        showMessage('エクスポートするデータがありません', true);
        return;
      }

      const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
      const csvData = storeOrders.map(order => {
        const product = products.find(p => p.id === order.商品ID) || {};
        const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};

        return [
          product.商品コード || '',
          product.商品名 || '',
          order.予測数量 || 0,
          order.発注数量 || 0,
          supplier.仕入先名 || '',
          order.発注金額 || 0,
          order.発注ステータス || '送信待ち'
        ];
      });

      const csvContent = '\uFEFF' + [headers, ...csvData]
        .map(row => row.map(cell => `"${cell}"`).join(','))
        .join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注送信データ_${today.replace(/\//g, '')}.csv`;
      link.click();

      showMessage('CSVファイルをエクスポートしました');
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      showMessage('CSVエクスポートに失敗しました', true);
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const errorDiv = container.querySelector("#error-message");

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      const storeSelect = container.querySelector("#store-select");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      if (stores) {
        stores.forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  // エラーメッセージ非表示
  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td><a href="#" class="product-detail-link" data-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ""}</a></td>
        <td>${r.商品コード || ""}</td>
        <td>${r.予測需要量 || 0}</td>
        <td>${r.現在在庫 || 0}</td>
        <td>${r.安全在庫 || 0}</td>
        <td>${r.発注点 || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td>¥${(r.発注金額 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${r.id}">発注実行</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ描画
  renderResults(tables[9]?.records || []);

  // 店舗データ読み込み
  loadStores();

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", async () => {
    hideError();

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = container.querySelector("#safety-stock").value;
    const leadTime = container.querySelector("#lead-time").value;
    const orderPoint = container.querySelector("#order-point").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください。");
      return;
    }
    if (!category) {
      showError("商品カテゴリを選択してください。");
      return;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください。");
      return;
    }
    if (safetyStock && parseInt(safetyStock) < 0) {
      showError("安全在庫数は0以上の値を入力してください。");
      return;
    }
    if (leadTime && parseInt(leadTime) <= 0) {
      showError("リードタイムは1以上の値を入力してください。");
      return;
    }
    if (orderPoint && parseInt(orderPoint) < 0) {
      showError("発注点は0以上の値を入力してください。");
      return;
    }

    try {
      // 需要予測データ取得
      const forecastData = await window.aivicApi.list(8);
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました。");
        return;
      }

      // 商品データ取得
      const products = await window.aivicApi.list(2);
      if (!products) {
        showError("商品データの取得に失敗しました。");
        return;
      }

      // 在庫データ取得（売上実績から推定）
      const salesData = await window.aivicApi.list(3);
      if (!salesData) {
        showError("在庫データの取得に失敗しました。");
        return;
      }

      // カテゴリに該当する商品をフィルタ
      const categoryProducts = products.filter(p => {
        // 簡易的なカテゴリ判定（実際はカテゴリマスタと連携）
        const productName = p.商品名 || "";
        if (category === "食品") return productName.includes("食品") || productName.includes("パン") || productName.includes("弁当");
        if (category === "日用品") return productName.includes("日用品") || productName.includes("洗剤") || productName.includes("ティッシュ");
        if (category === "衣料品") return productName.includes("衣料品") || productName.includes("シャツ") || productName.includes("靴下");
        return true;
      });

      // 計算結果生成
      const results = categoryProducts.map(product => {
        const forecast = forecastData.find(f => f.商品ID === product.id && f.店舗ID === storeId) || {};
        const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 100) + 50;
        const currentStock = Math.floor(Math.random() * 200) + 10;
        const safetyStockNum = parseInt(safetyStock) || 20;
        const leadTimeDays = parseInt(leadTime) || 7;
        const orderPointNum = parseInt(orderPoint) || (predictedDemand * leadTimeDays / 30 + safetyStockNum);

        // 発注量計算ロジック
        let recommendedOrder = 0;
        if (currentStock <= orderPointNum) {
          recommendedOrder = Math.max(0, predictedDemand + safetyStockNum - currentStock);
        }

        const orderAmount = recommendedOrder * (product.単価 || 100);

        return {
          id: `calc_${product.id}_${Date.now()}`,
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStockNum,
          発注点: orderPointNum,
          推奨発注量: recommendedOrder,
          発注金額: orderAmount
        };
      });

      // 結果表示
      renderResults(results);

      // サマリー表示更新
      const totalDemand = results.reduce((sum, r) => sum + r.予測需要量, 0);
      const totalStock = results.reduce((sum, r) => sum + r.現在在庫, 0);
      const totalOrder = results.reduce((sum, r) => sum + r.推奨発注量, 0);

      container.querySelector("#forecast-demand").textContent = totalDemand.toLocaleString();
      container.querySelector("#current-stock").textContent = totalStock.toLocaleString();
      container.querySelector("#recommended-order").textContent = totalOrder.toLocaleString();

    } catch (error) {
      showError("計算処理中にエラーが発生しました。");
    }
  });

  // 条件クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";
    hideError();
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const rows = Array.from(tbody.querySelectorAll("tr"));
    rows.forEach(row => {
      const text = row.textContent.toLowerCase();
      row.style.display = text.includes(keyword) ? "" : "none";
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    const rows = Array.from(tbody.querySelectorAll("tr:not([style*='display: none'])"));
    const headers = ["商品名", "商品コード", "予測需要量", "現在在庫", "安全在庫", "発注点", "推奨発注量", "発注金額"];

    let csvContent = "\uFEFF" + headers.join(",") + "\n";
    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td")).slice(0, 8);
      const rowData = cells.map(cell => {
        let text = cell.textContent.trim();
        if (text.includes(",")) text = `"${text}"`;
        return text;
      });
      csvContent += rowData.join(",") + "\n";
    });

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    // 商品詳細リンク
    const productLink = e.target.closest(".product-detail-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細:", productLink.dataset.id);
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      console.log("詳細表示:", id);
    }

    // 発注実行ボタン
    const orderBtn = e.target.closest(".order-btn");
    if (orderBtn) {
      const id = orderBtn.dataset.id;
      if (confirm("この商品の発注を実行しますか？")) {
        window.showScreen("scr-1778591960771"); // 発注実行画面
      }
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorMessage = container.querySelector("#error-message");
  const noResultsMessage = container.querySelector("#no-results-message");
  const storeSelect = container.querySelector("#store-select");

  // 店舗マスタのデータを店舗選択に設定
  const storeTable = tables.find(t => t.tableName === "店舗マスタ");
  if (storeTable && storeTable.records) {
    storeTable.records.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement("option");
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        storeSelect.appendChild(option);
      }
    });
  }

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock <= 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色分け
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "color: #ff6b6b;";
      case "過剰": return "color: #ffa726;";
      case "適正": return "color: #4caf50;";
      default: return "color: var(--text);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      noResultsMessage.classList.remove("hidden");
      return;
    }

    noResultsMessage.classList.add("hidden");
    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusStyle = getStatusColor(status);
      const updateTime = item.更新日時 ? new Date(item.更新日時).toLocaleString() : "";

      return `
        <tr data-id="${item.商品ID || ''}">
          <td>${item.商品コード || ""}</td>
          <td>${item.商品名 || ""}</td>
          <td style="${item.現在在庫数 === 0 ? 'color: #ff6b6b; font-weight: bold;' : ''}">${item.現在在庫数 || 0}</td>
          <td>${item.安全在庫数 || 0}</td>
          <td style="${statusStyle}">${status}</td>
          <td class="muted">${updateTime}</td>
        </tr>
      `;
    }).join("");
  }

  // 検索処理
  async function performSearch() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-filter").value;
    const productName = container.querySelector("#product-name-search").value.trim();
    const productCode = container.querySelector("#product-code-search").value.trim();
    const stockStatus = container.querySelector("#stock-status-filter").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i.test(productName)) {
      showError("商品名に無効な文字が含まれています");
      return;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return;
    }

    try {
      // 商品マスタを取得
      const productTable = tables.find(t => t.tableName === "商品マスタ");
      let products = productTable ? productTable.records || [] : [];

      // 在庫データを模擬生成（実際の実装では在庫テーブルから取得）
      let inventoryData = products.filter(p => p.有効フラグ).map(product => ({
        商品ID: product.商品ID,
        商品コード: product.商品コード,
        商品名: product.商品名,
        商品カテゴリ: product.商品カテゴリID === "cat1" ? "食品" : 
                     product.商品カテゴリID === "cat2" ? "日用品" : 
                     product.商品カテゴリID === "cat3" ? "衣料品" : "家電",
        現在在庫数: Math.floor(Math.random() * 200),
        安全在庫数: Math.floor(Math.random() * 50) + 10,
        更新日時: new Date().toISOString()
      }));

      // フィルタリング
      if (category) {
        inventoryData = inventoryData.filter(item => item.商品カテゴリ === category);
      }

      if (productName) {
        inventoryData = inventoryData.filter(item => 
          item.商品名 && item.商品名.toLowerCase().includes(productName.toLowerCase())
        );
      }

      if (productCode) {
        inventoryData = inventoryData.filter(item => 
          item.商品コード && item.商品コード.includes(productCode)
        );
      }

      if (stockStatus) {
        inventoryData = inventoryData.filter(item => {
          const status = getStockStatus(item.現在在庫数, item.安全在庫数);
          return status === stockStatus;
        });
      }

      renderRows(inventoryData);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-filter").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    tbody.innerHTML = "";
    noResultsMessage.classList.add("hidden");
  }

  // CSVエクスポート
  function exportToCSV() {
    const rows = Array.from(tbody.querySelectorAll("tr"));
    if (rows.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = [headers.join(",")];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td"));
      const rowData = cells.map(cell => {
        const text = cell.textContent.trim();
        return text.includes(",") ? `"${text}"` : text;
      });
      csvData.push(rowData.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enterキーで検索
  container.querySelector("#product-name-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#product-code-search").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  // 初期表示（空のテーブル）
  renderRows([]);
}

function(container, apiUrl, tables) {
  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // テーブルインデックスの定義
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const DEMAND_FORECAST_TABLE = 9;
  const ORDER_TABLE = 10;

  // 初期化処理
  async function initialize() {
    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#order-date').value = today;

    // データ読み込み
    await loadInitialData();

    // イベントリスナー設定
    setupEventListeners();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      storeData = await window.aivicApi.list(STORE_TABLE) || [];
      productData = await window.aivicApi.list(PRODUCT_TABLE) || [];
      demandForecastData = await window.aivicApi.list(DEMAND_FORECAST_TABLE) || [];

      populateStoreSelect();
      populateCategoryFilter();
      renderOrderTable([]);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を設定
  function populateStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    storeData.filter(store => store.有効フラグ).forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // カテゴリフィルター設定
  function populateCategoryFilter() {
    const categoryFilter = container.querySelector('#category-filter');
    categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>';

    const categories = [...new Set(productData.map(p => p.商品カテゴリID))];
    categories.forEach(categoryId => {
      if (categoryId) {
        const option = document.createElement('option');
        option.value = categoryId;
        option.textContent = `カテゴリ ${categoryId}`;
        categoryFilter.appendChild(option);
      }
    });
  }

  // 発注テーブル描画
  function renderOrderTable(orderItems) {
    const tbody = container.querySelector('#order-table-body');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!orderItems || orderItems.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');

    tbody.innerHTML = orderItems.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const forecast = demandForecastData.find(f => f.商品ID === item.商品ID && f.店舗ID === item.店舗ID) || {};

      return `
        <tr data-product-id="${item.商品ID}">
          <td><input type="checkbox" class="item-checkbox" data-product-id="${item.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${forecast.予測数量 || 0}</td>
          <td>${forecast.推奨発注数量 || 0}</td>
          <td>${item.現在在庫数量 || 0}</td>
          <td><input type="number" class="input order-quantity" data-product-id="${item.商品ID}" value="${forecast.推奨発注数量 || 0}" min="0" style="width: 80px;"></td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td class="order-amount" data-product-id="${item.商品ID}">¥0</td>
          <td><button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">個別発注</button></td>
        </tr>
      `;
    }).join('');

    // 金額計算
    updateAllAmounts();
  }

  // 全ての金額を更新
  function updateAllAmounts() {
    const quantityInputs = container.querySelectorAll('.order-quantity');
    quantityInputs.forEach(input => {
      updateOrderAmount(input.dataset.productId);
    });
    updateSummary();
  }

  // 個別商品の発注金額を更新
  function updateOrderAmount(productId) {
    const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
    const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
    const product = productData.find(p => p.商品ID === productId);

    if (quantityInput && amountCell && product) {
      const quantity = parseInt(quantityInput.value) || 0;
      const unitPrice = product.単価 || 0;
      const amount = quantity * unitPrice;
      amountCell.textContent = `¥${amount.toLocaleString()}`;
    }
  }

  // サマリー更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.item-checkbox:checked');
    const summaryDiv = container.querySelector('#order-summary');

    if (checkboxes.length === 0) {
      summaryDiv.style.display = 'none';
      container.querySelector('#btn-bulk-order').disabled = true;
      return;
    }

    summaryDiv.style.display = 'block';
    container.querySelector('#btn-bulk-order').disabled = false;

    let totalQuantity = 0;
    let totalAmount = 0;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const product = productData.find(p => p.商品ID === productId);

      if (quantityInput && product) {
        const quantity = parseInt(quantityInput.value) || 0;
        const unitPrice = product.単価 || 0;
        totalQuantity += quantity;
        totalAmount += quantity * unitPrice;
      }
    });

    container.querySelector('#selected-count').textContent = checkboxes.length;
    container.querySelector('#total-quantity').textContent = totalQuantity.toLocaleString();
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // 発注データ検索・表示更新
  async function searchOrderData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryId = container.querySelector('#category-filter').value;

    if (!storeId) {
      renderOrderTable([]);
      return;
    }

    // 選択された店舗と日付に基づいて発注対象商品を生成
    let filteredProducts = productData.filter(p => p.有効フラグ && p.AI予測対象フラグ);

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    const orderItems = filteredProducts.map(product => ({
      商品ID: product.商品ID,
      店舗ID: storeId,
      現在在庫数量: Math.floor(Math.random() * 100) // サンプル在庫数
    }));

    currentOrderData = orderItems;
    renderOrderTable(orderItems);
  }

  // バリデーション
  function validateOrderData(orderItems) {
    const errors = [];
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    if (!orderDate) {
      errors.push('発注日付を選択してください');
    } else {
      const today = new Date().toISOString().split('T')[0];
      if (orderDate < today) {
        errors.push('発注日付は本日以降の日付を選択してください');
      }
    }

    orderItems.forEach((item, index) => {
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${item.productId}"]`);
      if (quantityInput) {
        const quantity = quantityInput.value;

        if (!quantity || quantity === '') {
          errors.push(`商品${index + 1}: 発注数量を入力してください`);
        } else if (isNaN(quantity) || !Number.isInteger(parseFloat(quantity))) {
          errors.push(`商品${index + 1}: 発注数量は整数を入力してください`);
        } else if (parseFloat(quantity) <= 0) {
          errors.push(`商品${index + 1}: 発注数量は1以上の値を入力してください`);
        } else if (parseFloat(quantity) > 99999) {
          errors.push(`商品${index + 1}: 発注数量は99999以下で入力してください`);
        }
      }
    });

    return errors;
  }

  // 発注確認モーダル表示
  function showOrderConfirmModal(orderItems) {
    const modal = container.querySelector('#order-confirm-modal');
    const content = container.querySelector('#confirm-content');

    const storeSelect = container.querySelector('#store-select');
    const storeName = storeSelect.options[storeSelect.selectedIndex].text;
    const orderDate = container.querySelector('#order-date').value;

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const product = productData.find(p => p.商品ID === item.productId);
      const quantity = parseInt(item.quantity);
      const unitPrice = product.単価 || 0;
      const amount = quantity * unitPrice;
      totalAmount += amount;

      return `
        <tr>
          <td>${product.商品コード}</td>
          <td>${product.商品名}</td>
          <td>${quantity}</td>
          <td>¥${unitPrice.toLocaleString()}</td>
          <td>¥${amount.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    content.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>店舗:</strong> ${storeName}<br>
        <strong>発注日:</strong> ${orderDate}
      </div>
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr style="background: var(--bg-main);">
            <th style="padding: 8px; border: 1px solid var(--border);">商品コード</th>
            <th style="padding: 8px; border: 1px solid var(--border);">商品名</th>
            <th style="padding: 8px; border: 1px solid var(--border);">数量</th>
            <th style="padding: 8px; border: 1px solid var(--border);">単価</th>
            <th style="padding: 8px; border: 1px solid var(--border);">金額</th>
          </tr>
        </thead>
        <tbody>
          ${itemsHtml}
        </tbody>
      </table>
      <div style="margin-top: 15px; text-align: right;">
        <strong style="font-size: 1.2em; color: var(--primary);">合計金額: ¥${totalAmount.toLocaleString()}</strong>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder(orderItems) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    try {
      for (const item of orderItems) {
        const product = productData.find(p => p.商品ID === item.productId);
        const quantity = parseInt(item.quantity);
        const unitPrice = product.単価 || 0;

        const orderData = {
          店舗ID: storeId,
          商品ID: item.productId,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
          発注数量: quantity,
          発注単価: unitPrice,
          発注金額: quantity * unitPrice,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID || 'default-supplier',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      alert('発注が正常に実行されました');
      container.querySelector('#order-confirm-modal').classList.add('hidden');

      // チェックボックスをクリア
      container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
      container.querySelector('#select-all').checked = false;
      updateSummary();

    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 表示更新ボタン
    container.querySelector('#btn-search').addEventListener('click', searchOrderData);

    // 店舗選択変更
    container.querySelector('#store-select').addEventListener('change', searchOrderData);

    // カテゴリフィルター変更
    container.querySelector('#category-filter').addEventListener('change', searchOrderData);

    // 全選択チェックボックス
    container.querySelector('#select-all').addEventListener('change', function() {
      const checkboxes = container.querySelectorAll('.item-checkbox');
      checkboxes.forEach(cb => cb.checked = this.checked);
      updateSummary();
    });

    // 発注数量変更
    container.addEventListener('input', function(e) {
      if (e.target.classList.contains('order-quantity')) {
        updateOrderAmount(e.target.dataset.productId);
        updateSummary();
      }
    });

    // チェックボックス変更
    container.addEventListener('change', function(e) {
      if (e.target.classList.contains('item-checkbox')) {
        updateSummary();

        // 全選択チェックボックスの状態更新
        const allCheckboxes = container.querySelectorAll('.item-checkbox');
        const checkedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
        const selectAllCheckbox = container.querySelector('#select-all');

        if (checkedCheckboxes.length === 0) {
          selectAllCheckbox.indeterminate = false;
          selectAllCheckbox.checked = false;
        } else if (checkedCheckboxes.length === allCheckboxes.length) {
          selectAllCheckbox.indeterminate = false;
          selectAllCheckbox.checked = true;
        } else {
          selectAllCheckbox.indeterminate = true;
        }
      }
    });

    // まとめて発注実行ボタン
    container.querySelector('#btn-bulk-order').addEventListener('click', function() {
      const checkedBoxes = container.querySelectorAll('.item-checkbox:checked');
      const orderItems = Array.from(checkedBoxes).map(cb => {
        const productId = cb.dataset.productId;
        const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
        return {
          productId: productId,
          quantity: quantityInput.value
        };
      });

      const errors = validateOrderData(orderItems);
      if (errors.length > 0) {
        alert(errors.join('\n'));
        return;
      }

      showOrderConfirmModal(orderItems);
    });

    // 個別発注ボタン
    container.addEventListener('click', function(e) {
      if (e.target.classList.contains('single-order-btn')) {
        const productId = e.target.dataset.productId;
        const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);

        const orderItems = [{
          productId: productId,
          quantity: quantityInput.value
        }];

        const errors = validateOrderData(orderItems);
        if (errors.length > 0) {
          alert(errors.join('\n'));
          return;
        }

        showOrderConfirmModal(orderItems);
      }
    });

    // モーダル操作
    container.querySelector('#btn-cancel-order').addEventListener('click', function() {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    });

    container.querySelector('#btn-execute-order').addEventListener('click', function() {
      const checkedBoxes = container.querySelectorAll('.item-checkbox:checked');
      let orderItems;

      if (checkedBoxes.length > 0) {
        // まとめて発注の場合
        orderItems = Array.from(checkedBoxes).map(cb => {
          const productId = cb.dataset.productId;
          const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
          return {
            productId: productId,
            quantity: quantityInput.value
          };
        });
      } else {
        // 個別発注の場合（モーダルが開かれた商品）
        const modal = container.querySelector('#order-confirm-modal');
        const productRows = modal.querySelectorAll('tbody tr');
        orderItems = Array.from(productRows).map(row => {
          const cells = row.querySelectorAll('td');
          const productCode = cells[0].textContent;
          const product = productData.find(p => p.商品コード === productCode);
          const quantity = cells[2].textContent;
          return {
            productId: product.商品ID,
            quantity: quantity
          };
        });
      }

      executeOrder(orderItems);
    });

    // モーダル背景クリックで閉じる
    container.querySelector('#order-confirm-modal').addEventListener('click', function(e) {
      if (e.target === this) {
        this.classList.add('hidden');
      }
    });
  }

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 再描画関数の定義
  function renderRankingRows(rows) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const mape = row.予測精度 ? (100 - row.予測精度).toFixed(2) : '--';
      const rmse = row.推奨発注数量 && row.予測数量 ? Math.sqrt(Math.pow(row.推奨発注数量 - row.予測数量, 2)).toFixed(1) : '--';
      const accuracy = row.予測精度 || 0;
      const accuracyClass = accuracy >= 80 ? 'accuracy-high' : accuracy >= 60 ? 'accuracy-medium' : 'accuracy-low';

      return `
        <tr data-id="${row.id}">
          <td>${index + 1}</td>
          <td>${row.店舗名 || '--'}</td>
          <td>${row.商品名 || '--'}</td>
          <td>${row.商品カテゴリ || '--'}</td>
          <td>${mape}</td>
          <td>${rmse}</td>
          <td class="${accuracyClass}">${accuracy.toFixed(1)}%</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細分析</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // サマリー情報の更新
  function updateSummary(data) {
    if (!data || data.length === 0) {
      container.querySelector('#summary-mape').textContent = '--%';
      container.querySelector('#summary-rmse').textContent = '--';
      container.querySelector('#summary-products').textContent = '--';
      container.querySelector('#summary-alerts').textContent = '--';
      return;
    }

    const validData = data.filter(d => d.予測精度 != null);
    const avgAccuracy = validData.length > 0 ? validData.reduce((sum, d) => sum + d.予測精度, 0) / validData.length : 0;
    const avgMape = (100 - avgAccuracy).toFixed(1);

    const rmseValues = data.filter(d => d.推奨発注数量 && d.予測数量).map(d => Math.pow(d.推奨発注数量 - d.予測数量, 2));
    const avgRmse = rmseValues.length > 0 ? Math.sqrt(rmseValues.reduce((sum, val) => sum + val, 0) / rmseValues.length).toFixed(1) : 0;

    const alertCount = validData.filter(d => d.予測精度 < 70).length;

    container.querySelector('#summary-mape').textContent = avgMape + '%';
    container.querySelector('#summary-rmse').textContent = avgRmse;
    container.querySelector('#summary-products').textContent = data.length;
    container.querySelector('#summary-alerts').textContent = alertCount;
  }

  // グラフ描画
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // データポイントの描画
    if (data.length > 1) {
      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((d, i) => {
        const x = margin.left + (i / (data.length - 1)) * chartWidth;
        const y = margin.top + chartHeight - ((d.予測精度 || 0) / 100) * chartHeight;

        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // データポイント
      ctx.fillStyle = '#3182ce';
      data.forEach((d, i) => {
        const x = margin.left + (i / (data.length - 1)) * chartWidth;
        const y = margin.top + chartHeight - ((d.予測精度 || 0) / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, 2 * Math.PI);
        ctx.fill();
      });
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('時間', canvas.width / 2, canvas.height - 5);
    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('精度(%)', 0, 0);
    ctx.restore();
  }

  function drawPredictionVsActualChart(data) {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 50 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // 予測データ（青線）
    const predictionData = data.filter(d => d.予測数量);
    if (predictionData.length > 1) {
      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();
      predictionData.forEach((d, i) => {
        const x = margin.left + (i / (predictionData.length - 1)) * chartWidth;
        const maxVal = Math.max(...predictionData.map(d => d.予測数量));
        const y = margin.top + chartHeight - (d.予測数量 / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 実績データ（赤線）
    const actualData = data.filter(d => d.実績数量);
    if (actualData.length > 1) {
      ctx.strokeStyle = '#e53e3e';
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((d, i) => {
        const x = margin.left + (i / (actualData.length - 1)) * chartWidth;
        const maxVal = Math.max(...actualData.map(d => d.実績数量));
        const y = margin.top + chartHeight - (d.実績数量 / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 凡例
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(margin.left, 5, 15, 10);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測', margin.left + 20, 14);

    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(margin.left + 80, 5, 15, 10);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績', margin.left + 100, 14);
  }

  // アラート表示
  function updateAlerts(data) {
    const alertList = container.querySelector('#alert-list');
    const lowAccuracyData = data.filter(d => d.予測精度 && d.予測精度 < 70);

    if (lowAccuracyData.length === 0) {
      alertList.innerHTML = '<div class="muted">現在アラートはありません</div>';
      return;
    }

    alertList.innerHTML = lowAccuracyData.map(d => `
      <div style="padding: 10px; margin-bottom: 10px; background: rgba(255, 106, 0, 0.1); border-radius: 4px;">
        <strong>${d.店舗名} - ${d.商品名}</strong><br>
        <span class="muted">予測精度: ${d.予測精度.toFixed(1)}% (閾値: 70%未満)</span>
      </div>
    `).join('');
  }

  // データ読み込みとフィルタリング
  async function loadData() {
    try {
      const [predictionData, storeData, productData] = await Promise.all([
        window.aivicApi.list(8), // 需要予測結果
        window.aivicApi.list(1), // 店舗マスタ
        window.aivicApi.list(2)  // 商品マスタ
      ]);

      if (!predictionData || !storeData || !productData) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // データの結合
      const enrichedData = predictionData.map(pred => {
        const store = storeData.find(s => s.id === pred.店舗ID) || {};
        const product = productData.find(p => p.id === pred.商品ID) || {};
        return {
          ...pred,
          店舗名: store.店舗名,
          商品名: product.商品名,
          商品カテゴリ: product.商品カテゴリID // 簡略化
        };
      });

      currentData = enrichedData;
      applyFilters();

      // 店舗選択肢の更新
      const storeSelect = container.querySelector('#filter-store');
      storeSelect.innerHTML = '<option value="">全店舗</option>' + 
        storeData.map(s => `<option value="${s.id}">${s.店舗名}</option>`).join('');

    } catch (error) {
      showError('データの読み込み中にエラーが発生しました: ' + error.message);
    }
  }

  // フィルタ適用
  function applyFilters() {
    const period = parseInt(container.querySelector('#filter-period').value);
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;

    let filteredData = [...currentData];

    // 期間フィルタ
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - period);
    filteredData = filteredData.filter(d => {
      const predDate = new Date(d.予測対象日);
      return predDate >= cutoffDate;
    });

    // 店舗フィルタ
    if (storeId) {
      filteredData = filteredData.filter(d => d.店舗ID === storeId);
    }

    // カテゴリフィルタ
    if (category) {
      filteredData = filteredData.filter(d => d.商品カテゴリ === category);
    }

    // 表示更新
    updateSummary(filteredData);
    renderRankingRows(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawPredictionVsActualChart(filteredData);
    updateAlerts(filteredData);
    hideError();
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal = a[column] || '';
      let bVal = b[column] || '';

      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
      }

      aVal = aVal.toString().toLowerCase();
      bVal = bVal.toString().toLowerCase();

      if (sortDirection === 'asc') {
        return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      } else {
        return aVal > bVal ? -1 : aVal < bVal ? 1 : 0;
      }
    });

    applyFilters();
    updateSortIndicators();
  }

  function updateSortIndicators() {
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '↕';
    });

    if (sortColumn) {
      const indicator = container.querySelector(`#sort-${sortColumn.toLowerCase()} .sort-indicator`);
      if (indicator) {
        indicator.textContent = sortDirection === 'asc' ? '↑' : '↓';
      }
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // レポート出力
  function exportReport() {
    if (!currentData || currentData.length === 0) {
      showError('出力するデータがありません');
      return;
    }

    try {
      const headers = ['店舗名', '商品名', 'カテゴリ', '予測対象日', '予測数量', '実績数量', '予測精度(%)', 'MAPE(%)', 'RMSE'];
      const csvData = currentData.map(row => [
        row.店舗名 || '',
        row.商品名 || '',
        row.商品カテゴリ || '',
        row.予測対象日 || '',
        row.予測数量 || '',
        row.実績数量 || '',
        row.予測精度 ? row.予測精度.toFixed(1) : '',
        row.予測精度 ? (100 - row.予測精度).toFixed(2) : '',
        (row.推奨発注数量 && row.予測数量) ? Math.sqrt(Math.pow(row.推奨発注数量 - row.予測数量, 2)).toFixed(1) : ''
      ]);

      const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
        row.map(field => `"${field}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `prediction_accuracy_report_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      showError('レポート出力に失敗しました: ' + error.message);
    }
  }

  // 初期データ読み込み
  loadData();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);
  container.querySelector('#btn-export-report').addEventListener('click', exportReport);

  // 検索機能
  container.querySelector('#btn-search-ranking').addEventListener('click', () => {
    const keyword = container.querySelector('#search-ranking').value.toLowerCase();
    const filteredData = currentData.filter(row => 
      (row.商品名 || '').toLowerCase().includes(keyword) ||
      (row.店舗名 || '').toLowerCase().includes(keyword)
    );
    renderRankingRows(filteredData);
  });

  // ソートイベント
  ['rank', 'store', 'product', 'category', 'mape', 'rmse', 'accuracy'].forEach(col => {
    const header = container.querySelector(`#sort-${col}`);
    if (header) {
      header.addEventListener('click', () => {
        const columnMap = {
          'store': '店舗名',
          'product': '商品名', 
          'category': '商品カテゴリ',
          'mape': '予測精度',
          'rmse': '推奨発注数量',
          'accuracy': '予測精度'
        };
        sortData(columnMap[col] || col);
      });
    }
  });

  // 行レベル操作
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細分析画面への遷移（実装されていない場合のプレースホルダー）
      alert(`商品ID: ${id} の詳細分析画面に遷移します`);
    }
  });
}

function(container, apiUrl, tables) {
  // 店舗データを読み込んでドロップダウンに設定
  function loadStores() {
    const storeSelect = container.querySelector('#target-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector('#learning-rate');
    const display = container.querySelector('#learning-rate-value');
    slider.addEventListener('input', () => {
      display.textContent = parseFloat(slider.value).toFixed(5);
    });
  }

  // 重み付けの合計値計算
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll('.weight-input');
    const totalDisplay = container.querySelector('#weight-total');

    function calculateTotal() {
      let total = 0;
      weightInputs.forEach(input => {
        total += parseInt(input.value) || 0;
      });
      totalDisplay.textContent = total;
      totalDisplay.style.color = total === 100 ? 'var(--text)' : '#ff6a00';
    }

    weightInputs.forEach(input => {
      input.addEventListener('input', calculateTotal);
    });
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // モデル名チェック
    const modelName = container.querySelector('#model-name').value.trim();
    if (!modelName) {
      errors.push('モデル名を入力してください');
    }

    // 対象店舗チェック
    const targetStore = container.querySelector('#target-store').value;
    if (!targetStore) {
      errors.push('対象店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('#product-categories input[type="checkbox"]:checked');
    if (selectedCategories.length === 0) {
      errors.push('対象商品カテゴリを選択してください');
    }

    // 学習期間チェック
    const startDate = container.querySelector('#learning-start-date').value;
    const endDate = container.querySelector('#learning-end-date').value;
    if (!startDate || !endDate) {
      errors.push('学習期間を設定してください');
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start > end) {
        errors.push('開始日は終了日より前の日付を設定してください');
      }
      if (start > today || end > today) {
        errors.push('学習期間に未来の日付は設定できません');
      }
    }

    // 予測期間チェック
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked');
    if (!predictionPeriod) {
      errors.push('予測期間を選択してください');
    }

    // データソースチェック
    const selectedDataSources = container.querySelectorAll('#data-sources input[type="checkbox"]:checked');
    if (selectedDataSources.length === 0) {
      errors.push('データソースを選択してください');
    }

    // アルゴリズムチェック
    const algorithm = container.querySelector('#algorithm').value;
    if (!algorithm) {
      errors.push('アルゴリズムを選択してください');
    }

    // 精度目標値チェック
    const accuracyTarget = parseInt(container.querySelector('#accuracy-target').value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push('モデル精度目標値は0-100%の範囲で設定してください');
    }

    // 重み付け合計チェック
    const weightTotal = parseInt(container.querySelector('#weight-total').textContent);
    if (weightTotal !== 100) {
      errors.push('重み付けの合計値は100%にしてください');
    }

    // 季節性パラメータの数値チェック
    const seasonalStrength = container.querySelector('#seasonal-strength').value;
    const trendStrength = container.querySelector('#trend-strength').value;
    if (isNaN(seasonalStrength) || isNaN(trendStrength)) {
      errors.push('季節性パラメータには数値を入力してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorDiv = container.querySelector('#error-messages');
    if (errors.length > 0) {
      errorDiv.innerHTML = '<ul>' + errors.map(err => `<li>${err}</li>`).join('') + '</ul>';
      errorDiv.classList.remove('hidden');
    } else {
      errorDiv.classList.add('hidden');
    }
  }

  // フォームデータ収集
  function collectFormData() {
    const selectedCategories = Array.from(container.querySelectorAll('#product-categories input[type="checkbox"]:checked'))
      .map(cb => cb.value);
    const selectedDataSources = Array.from(container.querySelectorAll('#data-sources input[type="checkbox"]:checked'))
      .map(cb => cb.value);
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked')?.value;

    const weights = {};
    container.querySelectorAll('.weight-input').forEach(input => {
      weights[input.dataset.factor] = parseInt(input.value) || 0;
    });

    return {
      モデル名: container.querySelector('#model-name').value.trim(),
      対象店舗ID: container.querySelector('#target-store').value,
      対象商品カテゴリ: selectedCategories.join(','),
      学習期間開始日: container.querySelector('#learning-start-date').value,
      学習期間終了日: container.querySelector('#learning-end-date').value,
      予測期間: predictionPeriod,
      使用データソース: selectedDataSources.join(','),
      アルゴリズム: container.querySelector('#algorithm').value,
      学習率: parseFloat(container.querySelector('#learning-rate').value),
      重み付け設定: JSON.stringify(weights),
      季節性強度: parseFloat(container.querySelector('#seasonal-strength').value),
      トレンド強度: parseFloat(container.querySelector('#trend-strength').value),
      異常値除外フラグ: container.querySelector('#exclude-outliers').checked,
      祝日除外フラグ: container.querySelector('#exclude-holidays').checked,
      特別イベント除外フラグ: container.querySelector('#exclude-special-events').checked,
      精度目標値: parseInt(container.querySelector('#accuracy-target').value),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };
  }

  // フォームリセット
  function resetForm() {
    container.querySelector('#model-name').value = '';
    container.querySelector('#target-store').value = '';
    container.querySelectorAll('#product-categories input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#learning-start-date').value = '';
    container.querySelector('#learning-end-date').value = '';
    container.querySelectorAll('input[name="prediction-period"]').forEach(rb => rb.checked = false);
    container.querySelectorAll('#data-sources input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#algorithm').value = '';
    container.querySelector('#learning-rate').value = '0.01';
    container.querySelector('#learning-rate-value').textContent = '0.01';
    container.querySelectorAll('.weight-input').forEach((input, index) => {
      input.value = [40, 20, 20, 20][index];
    });
    container.querySelector('#seasonal-strength').value = '1.0';
    container.querySelector('#trend-strength').value = '1.0';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('#accuracy-target').value = '85';
    container.querySelector('#weight-total').textContent = '100';
    container.querySelector('#error-messages').classList.add('hidden');
  }

  // 初期化
  loadStores();
  updateLearningRateDisplay();
  updateWeightTotal();

  // 保存ボタンのイベントリスナー
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const errors = validateForm();
    showErrors(errors);

    if (errors.length === 0) {
      const formData = collectFormData();

      // 既存モデル名チェック（簡易実装）
      const existingModels = await window.aivicApi.list(0);
      if (existingModels && existingModels.some(model => model.モデル名 === formData.モデル名)) {
        showErrors(['このモデル名は既に使用されています']);
        return;
      }

      const saved = await window.aivicApi.save(0, formData);
      if (saved) {
        alert('モデルが正常に作成されました');
        resetForm();
      }
    }
  });

  // テストボタンのイベントリスナー
  container.querySelector('#btn-test').addEventListener('click', () => {
    const errors = validateForm();
    if (errors.length === 0) {
      window.showScreen('scr-1778591999045'); // モデルテスト機能画面
    } else {
      showErrors(errors);
    }
  });

  // リセットボタンのイベントリスナー
  container.querySelector('#btn-reset').addEventListener('click', () => {
    if (confirm('入力内容をリセットしますか？')) {
      resetForm();
    }
  });
}

function(container, apiUrl, tables) {
  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.実行日時 || ""}</td>
        <td>${r.モデル名 || ""}</td>
        <td>${r.テスト期間 || ""}</td>
        <td>${r.対象店舗数 || ""}</td>
        <td>${r.MAPE || ""}</td>
        <td>${r.RMSE || ""}</td>
        <td>${r.実行時間 || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  renderTestHistory(tables[0]?.records || []);

  // 全店舗選択チェックボックスの処理
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll(".store-checkbox");

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // 全カテゴリ選択チェックボックスの処理
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll(".category-checkbox");

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(checkbox => {
      checkbox.checked = this.checked;
    });
  });

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loadingDiv = container.querySelector("#loading-indicator");
    if (show) {
      loadingDiv.classList.remove("hidden");
    } else {
      loadingDiv.classList.add("hidden");
    }
  }

  // バリデーション関数
  function validateTestConfig() {
    const modelSelect = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const selectedStores = container.querySelectorAll(".store-checkbox:checked");
    const selectedCategories = container.querySelectorAll(".category-checkbox:checked");
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!modelSelect) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (selectedStores.length === 0) {
      showError("対象店舗を選択してください。");
      return false;
    }

    if (selectedCategories.length === 0) {
      showError("対象商品カテゴリを選択してください。");
      return false;
    }

    if (!selectedDataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(mape, rmse, mae, r2) {
    container.querySelector("#mape-value").textContent = mape + "%";
    container.querySelector("#rmse-value").textContent = rmse;
    container.querySelector("#mae-value").textContent = mae;
    container.querySelector("#r2-value").textContent = r2;
  }

  // 実行時間の更新
  function updateExecutionTime(time) {
    container.querySelector("#execution-time").textContent = time + "秒";
  }

  // モデルパラメータの更新
  function updateModelParameters(params) {
    container.querySelector("#training-period").textContent = params.trainingPeriod || "-";
    container.querySelector("#feature-count").textContent = params.featureCount || "-";
    container.querySelector("#algorithm").textContent = params.algorithm || "-";
    container.querySelector("#hyperparameters").textContent = params.hyperparameters || "-";
  }

  // 比較グラフの描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const allValues = [...actualData, ...predictedData];
    const maxValue = Math.max(...allValues);
    const minValue = Math.min(...allValues);
    const valueRange = maxValue - minValue;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値の線グラフ
    if (actualData.length > 0) {
      ctx.strokeStyle = '#4a9eff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }

    // 予測値の線グラフ
    if (predictedData.length > 0) {
      ctx.strokeStyle = '#ff6a00';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - ((value - minValue) / valueRange) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', canvas.width - 150, 30);
    ctx.fillText('予測値', canvas.width - 150, 50);

    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 25);
    ctx.lineTo(canvas.width - 155, 25);
    ctx.stroke();

    ctx.strokeStyle = '#ff6a00';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(canvas.width - 170, 45);
    ctx.lineTo(canvas.width - 155, 45);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // テスト実行ボタンのイベントリスナー
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    if (!validateTestConfig()) {
      return;
    }

    showLoading(true);

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // サンプル結果の表示
      updateMetrics(12.5, 45.2, 38.7, 0.85);
      updateExecutionTime(127);
      updateModelParameters({
        trainingPeriod: "2023/01/01 - 2023/12/31",
        featureCount: 25,
        algorithm: "Random Forest",
        hyperparameters: "n_estimators=100, max_depth=10"
      });

      // サンプルデータでグラフ描画
      const actualData = [100, 120, 95, 140, 110, 130, 105, 125, 115, 135];
      const predictedData = [105, 115, 100, 135, 115, 125, 110, 120, 120, 130];
      drawComparisonChart(actualData, predictedData);

      // テスト履歴に追加
      const testResult = {
        実行日時: new Date().toLocaleString(),
        モデル名: container.querySelector("#model-select").value,
        テスト期間: `${container.querySelector("#start-date").value} - ${container.querySelector("#end-date").value}`,
        対象店舗数: container.querySelectorAll(".store-checkbox:checked").length,
        MAPE: "12.5%",
        RMSE: "45.2",
        実行時間: "127秒"
      };

      const saved = await window.aivicApi.save(0, testResult);
      if (saved) {
        const rows = await window.aivicApi.list(0);
        if (rows) renderTestHistory(rows);
      }

    } catch (error) {
      showError("テスト実行中にエラーが発生しました: " + error.message);
    } finally {
      showLoading(false);
    }
  });

  // エクスポートボタンのイベントリスナー
  container.querySelector("#btn-test-export").addEventListener("click", async function() {
    try {
      const rows = await window.aivicApi.list(0);
      if (!rows || rows.length === 0) {
        showError("エクスポートするデータがありません");
        return;
      }

      const headers = ["実行日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        rows.map(row => [
          row.実行日時 || "",
          row.モデル名 || "",
          row.テスト期間 || "",
          row.対象店舗数 || "",
          row.MAPE || "",
          row.RMSE || "",
          row.実行時間 || ""
        ].map(field => `"${field}"`).join(",")).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "model_test_results.csv";
      link.click();

    } catch (error) {
      showError("エクスポート中にエラーが発生しました: " + error.message);
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      try {
        await window.aivicApi.delete(0, deleteBtn.dataset.id);
        const rows = await window.aivicApi.list(0);
        if (rows) renderTestHistory(rows);
      } catch (error) {
        showError("削除中にエラーが発生しました: " + error.message);
      }
    }

    const viewDetailBtn = e.target.closest(".view-detail-btn");
    if (viewDetailBtn) {
      // 詳細表示の実装（今回は省略）
      showError("詳細表示機能は実装中です");
    }
  });

  // 初期データの読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderTestHistory(rows);
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let selectedModel = null;
  let isProcessing = false;
  let progressInterval = null;

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="background: rgba(220, 53, 69, 0.1); border: 1px solid #dc3545; color: var(--text); padding: 1rem; border-radius: 4px; margin: 0.5rem 0;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 5000);
  }

  // ログ追加関数
  function addLog(message, type = 'info') {
    const logDisplay = container.querySelector('#log-display');
    const timestamp = new Date().toLocaleString();
    const color = type === 'error' ? '#dc3545' : type === 'success' ? '#28a745' : 'var(--text)';
    logDisplay.innerHTML += `<div style="color: ${color}; margin: 0.2rem 0;">[${timestamp}] ${message}</div>`;
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // モデル一覧の読み込み
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9);
      if (predictions) {
        const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン))];
        currentModels = modelVersions.map((version, index) => ({
          id: `model_${index}`,
          version: version,
          status: Math.random() > 0.3 ? '検証済み' : '検証中',
          accuracy: Math.floor(Math.random() * 20 + 80),
          created: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString()
        }));
      }

      const modelSelect = container.querySelector('#model-select');
      modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
        currentModels.map(model => 
          `<option value="${model.id}">${model.version} (精度: ${model.accuracy}%, ${model.status})</option>`
        ).join('');
    } catch (error) {
      showError('モデル一覧の読み込みに失敗しました');
    }
  }

  // 店舗一覧の読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1);
      if (stores) {
        currentStores = stores.filter(s => s.有効フラグ);
        const storeList = container.querySelector('#store-list');
        storeList.innerHTML = currentStores.map(store => 
          `<label style="display: block; margin: 0.3rem 0;">
            <input type="checkbox" class="store-checkbox" value="${store.店舗ID}"> 
            ${store.店舗名} (${store.店舗コード})
          </label>`
        ).join('');
      }
    } catch (error) {
      showError('店舗一覧の読み込みに失敗しました');
    }
  }

  // モデル詳細表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (!model) return;

    selectedModel = model;
    const detailsDiv = container.querySelector('#model-details');
    const infoDiv = container.querySelector('#model-info');

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
        <div><strong>モデルバージョン:</strong> ${model.version}</div>
        <div><strong>ステータス:</strong> ${model.status}</div>
        <div><strong>予測精度:</strong> ${model.accuracy}%</div>
        <div><strong>作成日時:</strong> ${new Date(model.created).toLocaleString()}</div>
      </div>
    `;
    detailsDiv.classList.remove('hidden');

    // 検証実行
    runValidation();
  }

  // 適用前検証実行
  function runValidation() {
    const validationDiv = container.querySelector('#validation-results');
    validationDiv.innerHTML = '<p style="color: var(--primary);">検証実行中...</p>';

    setTimeout(() => {
      const isValid = selectedModel && selectedModel.status === '検証済み' && selectedModel.accuracy >= 75;
      const validationHtml = `
        <div style="display: grid; gap: 0.5rem;">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: ${isValid ? '#28a745' : '#dc3545'};">●</span>
            <span>データ品質チェック: ${isValid ? 'OK' : 'NG'}</span>
          </div>
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: ${selectedModel?.accuracy >= 80 ? '#28a745' : '#ffc107'};">●</span>
            <span>精度閾値チェック: ${selectedModel?.accuracy}% (閾値: 80%)</span>
          </div>
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: #28a745;">●</span>
            <span>互換性チェック: OK</span>
          </div>
        </div>
      `;
      validationDiv.innerHTML = validationHtml;

      // 適用実行ボタンの状態更新
      updateExecuteButton();
    }, 1500);
  }

  // 影響範囲分析
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const impactDiv = container.querySelector('#impact-analysis');

    if (selectedStores.length === 0) {
      impactDiv.innerHTML = '<p class="muted">適用対象を選択すると影響範囲が表示されます</p>';
      return;
    }

    const storeCount = selectedStores.length;
    const totalStores = currentStores.length;
    const impactPercentage = Math.round((storeCount / totalStores) * 100);

    impactDiv.innerHTML = `
      <div style="display: grid; gap: 0.5rem;">
        <div><strong>対象店舗数:</strong> ${storeCount} / ${totalStores} 店舗 (${impactPercentage}%)</div>
        <div><strong>予想処理時間:</strong> 約${Math.ceil(storeCount * 2)}分</div>
        <div><strong>影響する機能:</strong> 需要予測、自動発注、在庫管理</div>
        <div><strong>ダウンタイム:</strong> なし（無停止切替）</div>
      </div>
    `;

    updateExecuteButton();
  }

  // 適用実行ボタンの状態更新
  function updateExecuteButton() {
    const executeBtn = container.querySelector('#btn-execute');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;
    const validationOk = selectedModel && selectedModel.status === '検証済み';

    const canExecute = selectedModel && selectedStores.length > 0 && startDateTime && validationOk && !isProcessing;
    executeBtn.disabled = !canExecute;
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}% - ${message}`;
  }

  // 適用実行処理
  async function executeDeployment() {
    if (!confirm('選択したモデルを本番環境に適用しますか？')) return;

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute');
    const rollbackBtn = container.querySelector('#btn-rollback');
    const progressSection = container.querySelector('#progress-section');

    executeBtn.disabled = true;
    rollbackBtn.disabled = true;
    progressSection.classList.remove('hidden');

    addLog('モデル本番適用処理を開始します', 'info');

    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));
    const totalSteps = selectedStores.length * 3; // 各店舗で3ステップ
    let currentStep = 0;

    try {
      // バックアップ作成
      if (container.querySelector('#backup-setting').checked) {
        updateProgress(5, 'バックアップ作成中...');
        addLog('現行モデルのバックアップを作成中');
        await new Promise(resolve => setTimeout(resolve, 2000));
        addLog('バックアップ作成完了', 'success');
      }

      // 各店舗への適用
      for (const storeCheckbox of selectedStores) {
        const storeId = storeCheckbox.value;
        const store = currentStores.find(s => s.店舗ID === storeId);

        // ステップ1: モデル検証
        currentStep++;
        const progress1 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress1, `${store.店舗名}: モデル検証中...`);
        addLog(`${store.店舗名}: モデル検証を実行中`);
        await new Promise(resolve => setTimeout(resolve, 1000));

        // ステップ2: デプロイメント
        currentStep++;
        const progress2 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress2, `${store.店舗名}: デプロイ中...`);
        addLog(`${store.店舗名}: モデルデプロイメント実行中`);
        await new Promise(resolve => setTimeout(resolve, 1500));

        // ステップ3: 本番切替
        currentStep++;
        const progress3 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress3, `${store.店舗名}: 本番切替中...`);
        addLog(`${store.店舗名}: 本番環境への切替実行中`);
        await new Promise(resolve => setTimeout(resolve, 1000));

        addLog(`${store.店舗名}: 適用完了`, 'success');
      }

      // 最終確認
      updateProgress(95, '最終確認中...');
      addLog('全店舗への適用完了、最終確認実行中');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(100, '適用完了');
      addLog('モデル本番適用処理が正常に完了しました', 'success');

      rollbackBtn.disabled = false;

    } catch (error) {
      addLog(`エラーが発生しました: ${error.message}`, 'error');
      showError('適用処理中にエラーが発生しました');
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
    }
  }

  // ロールバック実行
  async function executeRollback() {
    if (!confirm('前のモデルにロールバックしますか？')) return;

    addLog('ロールバック処理を開始します', 'info');
    updateProgress(0, 'ロールバック準備中...');

    try {
      updateProgress(25, 'バックアップモデル確認中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(50, 'モデル切替中...');
      addLog('前バージョンモデルに切替中');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(75, '動作確認中...');
      addLog('ロールバック後の動作確認実行中');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(100, 'ロールバック完了');
      addLog('ロールバック処理が正常に完了しました', 'success');

    } catch (error) {
      addLog(`ロールバックエラー: ${error.message}`, 'error');
      showError('ロールバック処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    if (e.target.value) {
      showModelDetails(e.target.value);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      selectedModel = null;
    }
    updateExecuteButton();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();
    }
    if (e.target.id === 'start-datetime') {
      const selectedDate = new Date(e.target.value);
      const now = new Date();
      if (selectedDate < now) {
        showError('適用開始日時には現在日時以降を指定してください');
        e.target.value = '';
      }
      updateExecuteButton();
    }
  });

  container.querySelector('#retention-period').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value < 1 || value > 9999) {
      showError('保持期間は1〜9999日の範囲で入力してください');
    }
  });

  container.querySelector('#btn-execute').addEventListener('click', executeDeployment);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  loadModels();
  loadStores();

  // 現在時刻を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);
}
